// Beytepe scene edits on top of the RoadRunner model (Beytepe.fbx), driven by ONE data file:
//   Assets/Beytepe/Data/duzenlemeler.json, generated by husmart-sim/tools/beytepe_duzenle ("duzenle.py awsim").
// Sections (ROS map frame x, y, z):
//   nizamiye : main gate road. 0.5 m grids: terrain target height + weight (road level, 8 m cut/fill slope around it),
//              grass mask (old loop that is no longer road), marking-removal mask, road mask (tree hiding);
//              asphalt mesh of the new lanes + drawn asphalt areas, lane markings, bus shelter pose.
//   refuj    : median island between the two carriageways (campus junction -> gate): curbs, grass, concrete curb faces,
//              two-arm lamps, trees / bushes, outline, and the regions sampled for the point-cloud map.
//   nesneler : permanent objects at the gate measured from the real drive: entry barriers (arms up), flagpoles, red guard
//              kiosk, pedestrian-crossing sign, generator, banner poles, trash bin, stone wall, guardrail, wire fence.
// The FBX is never modified: edited meshes are copies stored in the scene. A missing file or section changes nothing.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;

namespace Beytepe.EditorTools
{
    public static partial class BeytepeSceneBuilder
    {
        const string EditDataPath = "Assets/Beytepe/Data/duzenlemeler.json";
        const string MedianLampMatPath = "Assets/Beytepe/Materials/Refuj_Lamba.mat";
        static string EditCloudPath => Environment.GetEnvironmentVariable("BEYTEPE_NIZAMIYE_BULUT")
                                       ?? Path.Combine(Home, "awsim/beytepe_nizamiye_bulut.bin");

        // ---------------- data ----------------
        [Serializable] class NizamiyeDurak { public float x, y, z, yaw_deg; }
        [Serializable] class NizamiyeVeri
        {
            public float x0, y0, cozunurluk; public int nx, ny;
            public string zemin_hedef, zemin_agirlik, cim_maske, cizgi_sil_maske, yol_maske, agacsiz_maske;
            public float[] asfalt_v; public int[] asfalt_t; public float[] cizgi_v; public int[] cizgi_t;   // white (dashed) lines
            public float[] cizgi_sari_v; public int[] cizgi_sari_t;                                          // yellow (solid) lines
            public NizamiyeDurak durak; public float[] bulut_kutu; public float bulut_yogunluk;
        }
        [Serializable] class RefujLamba { public string ad; public float x, y, z, yol_yonu_deg, boy, kol; }
        [Serializable] class RefujAgac { public string tur; public float x, y, z, boy, tac; }
        [Serializable] class RefujAlan { public float[] xy; }
        [Serializable] class RefujVeri
        {
            public float[] sinir_xy, kaldirim_v, cim_v, bordur_v, asfalt_v; public int[] kaldirim_t, cim_t, bordur_t, asfalt_t;
            public RefujAlan[] ek_sinirlar;   // outlines of the other raised islands (gate) that share these meshes
            public RefujLamba[] lambalar; public RefujAgac[] agaclar; public RefujAlan[] bulut_alanlari;
        }
        // RoadRunner marking recolouring: region + lanelet lines as segments (x0, y0, x1, y1, ...): solid -> yellow, dashed -> white
        [Serializable] class CizgiRenkVeri { public float[] bolge_xy, sari_xy, beyaz_xy; }
        // gate objects measured by hand (real lidar + ZED): barriers, flagpoles, kiosk, sign, generator, wall, guardrail, fence
        [Serializable] class NesneNokta { public string ad, bez, tur; public float x, y, kol_boy, boy, yuz_deg, yon_deg, en, derin, ust, boyut, cap, tac; public float[] renk; }
        [Serializable] class NesneDuvar { public string ad, tur; public float kalinlik; public float[] xy, boy; }
        [Serializable] class NesneCizgi { public string ad; public float boy; public float[] xy; }
        // big guard booth: body = rectangle + semicircular north end in a frame rotated by aci_deg (u across, v along);
        // openings: yuz dogu / bati (s from the south corner), guney (s from the west corner), yay (s = degrees from east)
        [Serializable] class KulubeAciklik { public string yuz, tur; public float s0, s1, alt, ust; }
        [Serializable] class BuyukKulube
        {
            public string ad, osm_id; public float x, y, aci_deg, yari_en, guney_v, yay_v, tavan, sacak_ust, tasma, tasma_guney;
            public KulubeAciklik[] acikliklar;
        }
        [Serializable] class NesneVeri
        {
            public NesneNokta[] bariyerler, bayraklar, kulubeler, tabelalar, kutular, panolar, cop_kutulari, yuvarlak_calilar, sus_agaclari;
            public BuyukKulube[] buyuk_kulubeler;
            public NesneDuvar[] duvarlar; public NesneCizgi[] korkuluklar, citler;
        }
        [Serializable] class DuzenlemeVeri { public string aciklama; public NizamiyeVeri nizamiye; public RefujVeri refuj; public CizgiRenkVeri cizgi_renk; public NesneVeri nesneler; }

        static DuzenlemeVeri LoadEdits() => File.Exists(EditDataPath) ? JsonUtility.FromJson<DuzenlemeVeri>(File.ReadAllText(EditDataPath)) : null;
        // JsonUtility fills a missing section with an empty object, so "present" means "has content"
        static bool Has(NizamiyeVeri n) => n != null && n.nx > 0 && n.ny > 0 && !string.IsNullOrEmpty(n.zemin_hedef);
        static bool Has(RefujVeri r) => r != null && r.sinir_xy != null && r.sinir_xy.Length >= 6;
        static bool Has(CizgiRenkVeri c) => c != null && c.bolge_xy != null && c.bolge_xy.Length >= 6;
        static int NLen<T>(T[] a) => a == null ? 0 : a.Length;
        static bool Has(NesneVeri n) => n != null && NLen(n.bariyerler) + NLen(n.bayraklar) + NLen(n.kulubeler) + NLen(n.tabelalar)
                                                     + NLen(n.kutular) + NLen(n.panolar) + NLen(n.cop_kutulari) + NLen(n.buyuk_kulubeler)
                                                     + NLen(n.yuvarlak_calilar) + NLen(n.sus_agaclari)
                                                     + NLen(n.duvarlar) + NLen(n.korkuluklar) + NLen(n.citler) > 0;

        // Called once while the scene is built (before the speed bumps and buildings).
        // OSM buildings replaced by a detailed model of the gate objects (AddBuildings hides them)
        static readonly HashSet<string> GateReplacedBuildings = new HashSet<string>();

        static void ApplyDuzenlemeler(GameObject model, Transform parent)
        {
            GateReplacedBuildings.Clear();
            if (model == null) return;
            var d = LoadEdits();
            if (d == null) { L("Düzenlemeler: veri yok (" + EditDataPath + "), RoadRunner modeli olduğu gibi kaldı"); return; }
            if (Has(d.nizamiye)) ApplyNizamiye(model, parent, d.nizamiye); else L("Nizamiye: veride bölüm yok, atlandı");
            if (Has(d.refuj)) ApplyRefuj(model, parent, d.refuj); else L("Refüj: veride bölüm yok, atlandı");
            if (Has(d.nizamiye) && d.nizamiye.durak != null && d.nizamiye.durak.x != 0f) { Physics.SyncTransforms(); AddBusStop(d.nizamiye.durak, parent); }
            if (Has(d.cizgi_renk)) RecolorMarkings(model, d.cizgi_renk);
            if (Has(d.nesneler)) AddGateObjects(parent, d.nesneler); else L("Nizamiye nesneleri: veride bölüm yok, atlandı");
            FixTrees(model, parent, d);   // after the gate objects: a tree standing in the wall / fence is hidden
        }

        class NizamiyeIzgara
        {
            public float x0, y0, r; public int nx, ny; public float[] hedef, agirlik; public byte[] cim, sil, yol, agacsiz;
            static float[] F32(string b) { var by = Convert.FromBase64String(b); var f = new float[by.Length / 4]; Buffer.BlockCopy(by, 0, f, 0, by.Length); return f; }
            public NizamiyeIzgara(NizamiyeVeri d)
            {
                x0 = d.x0; y0 = d.y0; r = d.cozunurluk; nx = d.nx; ny = d.ny;
                hedef = F32(d.zemin_hedef); agirlik = F32(d.zemin_agirlik);
                cim = Convert.FromBase64String(d.cim_maske); sil = Convert.FromBase64String(d.cizgi_sil_maske); yol = Convert.FromBase64String(d.yol_maske);
                agacsiz = string.IsNullOrEmpty(d.agacsiz_maske) ? yol : Convert.FromBase64String(d.agacsiz_maske);
                int n = nx * ny;
                if (hedef.Length != n || agirlik.Length != n || cim.Length != n || sil.Length != n || yol.Length != n || agacsiz.Length != n)
                    throw new Exception($"duzenlemeler.json nizamiye ızgara boyu tutmuyor ({nx}x{ny})");
            }
            // ROS (x, y) -> cell index, -1 outside
            public int Hucre(float x, float y)
            {
                int ix = Mathf.FloorToInt((x - x0) / r), iy = Mathf.FloorToInt((y - y0) / r);
                return (ix < 0 || iy < 0 || ix >= nx || iy >= ny) ? -1 : iy * nx + ix;
            }
            public bool Maske(byte[] m, float x, float y) { int c = Hucre(x, y); return c >= 0 && m[c] != 0; }
            // bilinear between cell centres; cells without a target (-999) count as weight 0
            public bool Zemin(float x, float y, out float hedefZ, out float w)
            {
                hedefZ = 0f; w = 0f;
                float fx = (x - x0) / r - 0.5f, fy = (y - y0) / r - 0.5f;
                int i0 = Mathf.FloorToInt(fx), j0 = Mathf.FloorToInt(fy);
                if (i0 < 0 || j0 < 0 || i0 + 1 >= nx || j0 + 1 >= ny) return false;
                float tx = fx - i0, ty = fy - j0, sw = 0f, sz = 0f, wsum = 0f;
                for (int dj = 0; dj < 2; dj++)
                    for (int di = 0; di < 2; di++)
                    {
                        int c = (j0 + dj) * nx + (i0 + di);
                        float k = (di == 0 ? 1 - tx : tx) * (dj == 0 ? 1 - ty : ty);
                        if (hedef[c] < -900f) continue;
                        sw += k * agirlik[c]; sz += k * hedef[c]; wsum += k;
                    }
                if (wsum < 1e-4f) return false;
                hedefZ = sz / wsum; w = sw;   // a missing corner pulls the weight to 0 (soft transition at the region edge)
                return w > 1e-4f;
            }
        }

        // ---------------- editable copy of a model mesh ----------------
        // Keeps every vertex attribute so triangles can be split (midpoints are shared between neighbours, no cracks),
        // vertices moved in world space, triangles moved between sub-meshes; Commit() puts the copy into the scene.
        class DuzenlenenMesh
        {
            public readonly MeshFilter mf; public readonly MeshRenderer mr; readonly Mesh src;
            public readonly Matrix4x4 l2w, w2l;
            public readonly List<Vector3> pos; public readonly List<float> top; public List<int>[] tris;
            readonly List<Vector3> nrm; readonly bool hasN; readonly List<Vector4> tan; readonly bool hasT;
            readonly List<Color> col; readonly bool hasC; readonly List<List<Vector4>> uvs = new List<List<Vector4>>(); readonly List<int> uvCh = new List<int>();
            readonly Dictionary<long, int> mid = new Dictionary<long, int>();
            public int nSplit;

            public DuzenlenenMesh(MeshFilter f, float[] top0)
            {
                mf = f; mr = f.GetComponent<MeshRenderer>(); src = f.sharedMesh;
                l2w = f.transform.localToWorldMatrix; w2l = f.transform.worldToLocalMatrix;
                pos = new List<Vector3>(src.vertices);
                top = top0 != null ? new List<float>(top0) : new List<float>(new float[pos.Count]);
                nrm = new List<Vector3>(src.normals); hasN = nrm.Count == pos.Count;
                tan = new List<Vector4>(src.tangents); hasT = tan.Count == pos.Count;
                col = new List<Color>(src.colors); hasC = col.Count == pos.Count;
                for (int ch = 0; ch < 8; ch++)
                {
                    if (!src.HasVertexAttribute((UnityEngine.Rendering.VertexAttribute)((int)UnityEngine.Rendering.VertexAttribute.TexCoord0 + ch))) continue;
                    var l = new List<Vector4>(); src.GetUVs(ch, l);
                    if (l.Count == pos.Count) { uvs.Add(l); uvCh.Add(ch); }
                }
                tris = new List<int>[src.subMeshCount];
                for (int s = 0; s < tris.Length; s++) tris[s] = new List<int>(src.GetTriangles(s));
            }

            public Vector3 W(int v) => l2w.MultiplyPoint3x4(pos[v]);
            public void SetW(int v, Vector3 w) => pos[v] = w2l.MultiplyPoint3x4(w);

            int Mid(int i, int j)
            {
                long key = i < j ? ((long)i << 32) | (uint)j : ((long)j << 32) | (uint)i;
                if (mid.TryGetValue(key, out var m)) return m;
                m = pos.Count;
                pos.Add((pos[i] + pos[j]) * 0.5f);
                top.Add((top[i] + top[j]) * 0.5f);
                if (hasN) nrm.Add((nrm[i] + nrm[j]).normalized);
                if (hasT) { var tt = (tan[i] + tan[j]) * 0.5f; tan.Add(new Vector4(tt.x, tt.y, tt.z, tan[i].w)); }
                if (hasC) col.Add((col[i] + col[j]) * 0.5f);
                foreach (var l in uvs) l.Add((l[i] + l[j]) * 0.5f);
                mid[key] = m; return m;
            }

            // Split triangles into four until every edge is <= maxEdge, wherever need(a, b, c) (world corners) says so.
            public void Subdivide(Func<Vector3, Vector3, Vector3, bool> need, float maxEdge = 1f, int maxDepth = 10)
            {
                for (int s = 0; s < tris.Length; s++)
                {
                    var outT = new List<int>(tris[s].Count);
                    var stack = new Stack<(int a, int b, int c, int depth)>();
                    var t0 = tris[s];
                    for (int k = 0; k + 2 < t0.Count; k += 3)
                    {
                        stack.Push((t0[k], t0[k + 1], t0[k + 2], 0));
                        while (stack.Count > 0)
                        {
                            var (ia, ib, ic, dep) = stack.Pop();
                            var wa = W(ia); var wb = W(ib); var wc = W(ic);
                            float maxE = Mathf.Max(Vector3.Distance(wa, wb), Mathf.Max(Vector3.Distance(wb, wc), Vector3.Distance(wc, wa)));
                            if (dep < maxDepth && maxE > maxEdge && need(wa, wb, wc))
                            {
                                int mab = Mid(ia, ib), mbc = Mid(ib, ic), mca = Mid(ic, ia);
                                stack.Push((ia, mab, mca, dep + 1)); stack.Push((mab, ib, mbc, dep + 1));
                                stack.Push((mca, mbc, ic, dep + 1)); stack.Push((mab, mbc, mca, dep + 1));
                                nSplit++;
                                continue;
                            }
                            outT.Add(ia); outT.Add(ib); outT.Add(ic);
                        }
                    }
                    tris[s] = outT;
                }
            }

            // Append triangles to the sub-mesh drawn with m (index idx; a new sub-mesh is made when idx < 0).
            public void AddTo(List<Material> mats, ref int idx, Material m, List<int> add)
            {
                if (add.Count == 0) return;
                if (idx < 0) { idx = mats.Count; mats.Add(m); }
                if (idx >= tris.Length) { int old = tris.Length; Array.Resize(ref tris, idx + 1); for (int z = old; z < tris.Length; z++) tris[z] = new List<int>(); }
                tris[idx].AddRange(add);
            }

            // Normals of moved vertices from their neighbouring triangles; mats may have grown (new sub-meshes).
            public void Commit(string suffix, bool[] changed, List<Material> mats)
            {
                if (hasN && changed != null)
                {
                    var acc = new Vector3[pos.Count];
                    foreach (var t in tris)
                        for (int k = 0; k + 2 < t.Count; k += 3)
                        {
                            int a = t[k], b = t[k + 1], c = t[k + 2];
                            if (!(changed[a] || changed[b] || changed[c])) continue;
                            var fn = Vector3.Cross(pos[b] - pos[a], pos[c] - pos[a]);
                            if (changed[a]) acc[a] += fn; if (changed[b]) acc[b] += fn; if (changed[c]) acc[c] += fn;
                        }
                    for (int v = 0; v < pos.Count; v++)
                        if (changed[v] && acc[v].sqrMagnitude > 1e-12f)
                        {
                            var nn = acc[v].normalized;
                            if (Vector3.Dot(nn, nrm[v]) < 0f) nn = -nn;
                            nrm[v] = nn;
                        }
                }
                var mesh = new Mesh { name = src.name + suffix, indexFormat = UnityEngine.Rendering.IndexFormat.UInt32 };
                mesh.SetVertices(pos);
                if (hasN) mesh.SetNormals(nrm);
                if (hasT) mesh.SetTangents(tan);
                if (hasC) mesh.SetColors(col);
                for (int u = 0; u < uvs.Count; u++) mesh.SetUVs(uvCh[u], uvs[u]);
                mesh.subMeshCount = tris.Length;
                for (int s = 0; s < tris.Length; s++) mesh.SetTriangles(tris[s] ?? new List<int>(), s, false);
                mesh.RecalculateBounds();
                mf.sharedMesh = mesh;
                PrefabUtility.RecordPrefabInstancePropertyModifications(mf);
                if (mats != null && mats.Count != mr.sharedMaterials.Length) { mr.sharedMaterials = mats.ToArray(); PrefabUtility.RecordPrefabInstancePropertyModifications(mr); }
                var mc = mf.GetComponent<MeshCollider>();
                if (mc != null) { mc.sharedMesh = null; mc.sharedMesh = mesh; PrefabUtility.RecordPrefabInstancePropertyModifications(mc); }
            }
        }

        // model meshes (not trees / foliage) whose renderer touches the Unity-space box
        static List<MeshFilter> TerrainMeshes(GameObject model, Bounds box) =>
            model.GetComponentsInChildren<MeshFilter>(true).Where(mf =>
            {
                var mr = mf.GetComponent<MeshRenderer>();
                if (mf.sharedMesh == null || mr == null || !mf.sharedMesh.isReadable) return false;
                if (NoColliderKeywords.Any(k => FullName(mf.transform).IndexOf(k, StringComparison.OrdinalIgnoreCase) >= 0)) return false;
                if (mf.name.StartsWith("Refuj_") || mf.name.StartsWith("Nizamiye_")) return false;
                return mr.bounds.Intersects(box);
            }).ToList();

        // ROS rectangle -> Unity bounds (ROS x -> Unity z, ROS y -> Unity -x)
        static Bounds RosBox(float x0, float x1, float y0, float y1)
        {
            var b = new Bounds(); b.SetMinMax(new Vector3(-y1, -1000f, x0), new Vector3(-y0, 1000f, x1)); return b;
        }

        static Vector3 UnityToRos(Vector3 u) => new Vector3(u.z, -u.x, u.y);

        static bool IsRoadLikeMat(string n) => new[] { "Asphalt", "Concrete1_Road", "Gutter", "Curb", "Sidewalk" }
            .Any(k => n.IndexOf(k, StringComparison.OrdinalIgnoreCase) >= 0);
        static bool IsMarkingMat(string n) => n.IndexOf("LaneMarking", StringComparison.OrdinalIgnoreCase) >= 0;

        static Material FindModelMaterial(GameObject model, Func<string, bool> pred)
        {
            foreach (var mr in model.GetComponentsInChildren<MeshRenderer>(true))
                foreach (var m in mr.sharedMaterials)
                    if (m != null && pred(m.name)) return m;
            return null;
        }

        static List<Vector2> XyList(float[] a)
        {
            var l = new List<Vector2>(a.Length / 2);
            for (int i = 0; i + 1 < a.Length; i += 2) l.Add(new Vector2(a[i], a[i + 1]));
            return l;
        }

        static bool InPoly(Vector2 p, List<Vector2> poly)
        {
            bool inside = false;
            for (int i = 0, j = poly.Count - 1; i < poly.Count; j = i++)
            {
                var a = poly[i]; var b = poly[j];
                if ((a.y > p.y) != (b.y > p.y) && p.x < (b.x - a.x) * (p.y - a.y) / (b.y - a.y) + a.x) inside = !inside;
            }
            return inside;
        }

        // Polygon rasterised once (scanline) so "inside?" is a lookup: the median outline has ~8000 points.
        class PolyMaske
        {
            readonly float x0, y0, r; readonly int nx, ny; readonly bool[] m;
            public PolyMaske(List<Vector2> poly, float res = 0.1f)
            {
                r = res; x0 = poly.Min(p => p.x) - r; y0 = poly.Min(p => p.y) - r;
                nx = Mathf.CeilToInt((poly.Max(p => p.x) + r - x0) / r) + 1; ny = Mathf.CeilToInt((poly.Max(p => p.y) + r - y0) / r) + 1;
                m = new bool[nx * ny]; var xs = new List<float>();
                for (int j = 0; j < ny; j++)
                {
                    float y = y0 + (j + 0.5f) * r; xs.Clear();
                    for (int i = 0, k = poly.Count - 1; i < poly.Count; k = i++)
                    {
                        var a = poly[i]; var b = poly[k];
                        if ((a.y > y) != (b.y > y)) xs.Add(a.x + (y - a.y) * (b.x - a.x) / (b.y - a.y));
                    }
                    xs.Sort();
                    for (int q = 0; q + 1 < xs.Count; q += 2)
                    {
                        int i0 = Mathf.Max(0, Mathf.CeilToInt((xs[q] - x0) / r - 0.5f)), i1 = Mathf.Min(nx - 1, Mathf.FloorToInt((xs[q + 1] - x0) / r - 0.5f));
                        for (int i = i0; i <= i1; i++) m[j * nx + i] = true;
                    }
                }
            }
            public bool In(float x, float y)
            {
                int i = Mathf.FloorToInt((x - x0) / r), j = Mathf.FloorToInt((y - y0) / r);
                return i >= 0 && j >= 0 && i < nx && j < ny && m[j * nx + i];
            }
        }

        // ================= gate road (nizamiye) =================
        static void ApplyNizamiye(GameObject model, Transform parent, NizamiyeVeri d)
        {
            var g = new NizamiyeIzgara(d);
            var matAsphalt = FindModelMaterial(model, n => n.IndexOf("Asphalt", StringComparison.OrdinalIgnoreCase) >= 0);
            var matGrass = FindModelMaterial(model, n => n.IndexOf("Grass", StringComparison.OrdinalIgnoreCase) >= 0);
            var matMark = FindModelMaterial(model, n => IsMarkingMat(n) && n.IndexOf("Yellow", StringComparison.OrdinalIgnoreCase) < 0);
            if (matAsphalt == null || matGrass == null) { L("UYARI: Nizamiye: asfalt/çim malzemesi bulunamadı, atlandı"); return; }

            var box = RosBox(g.x0, g.x0 + g.nx * g.r, g.y0, g.y0 + g.ny * g.r);
            int nMesh = 0, nVert = 0, nGrass = 0, nMarkDel = 0, nCurb = 0, nSplit = 0, nSkirt = 0;
            var targets = TerrainMeshes(model, box);
            // Original top-surface height (rays from above onto the unmodified colliders). Vertices more than 5 cm below
            // the surface (skirts between road and terrain, under curbs) move WITH the surface instead of being flattened.
            Physics.SyncTransforms();
            var topH = new Dictionary<MeshFilter, float[]>();
            foreach (var mf in targets)
            {
                var vv = mf.sharedMesh.vertices; var l2wp = mf.transform.localToWorldMatrix; var h = new float[vv.Length];
                for (int v = 0; v < vv.Length; v++)
                {
                    var w = l2wp.MultiplyPoint3x4(vv[v]); h[v] = w.y;
                    if (!box.Contains(w)) continue;
                    var ros = UnityToRos(w);
                    if (!g.Zemin(ros.x, ros.y, out _, out _)) continue;
                    if (Physics.Raycast(new Vector3(w.x, w.y + 30f, w.z), Vector3.down, out var hit, 60f, ~0, QueryTriggerInteraction.Ignore)) h[v] = hit.point.y;
                }
                topH[mf] = h;
            }
            bool Relevant(Vector3 wa, Vector3 wb)   // every 0.5 m along the edge: regrade weight or a mask?
            {
                int n = Mathf.Max(1, Mathf.CeilToInt(Vector3.Distance(wa, wb) / 0.5f));
                for (int k = 0; k <= n; k++)
                {
                    var q = Vector3.Lerp(wa, wb, k / (float)n);
                    if (!box.Contains(q)) continue;
                    var r = UnityToRos(q);
                    if (g.Zemin(r.x, r.y, out _, out _) || g.Maske(g.cim, r.x, r.y) || g.Maske(g.sil, r.x, r.y)) return true;
                }
                return false;
            }
            foreach (var mf in targets)
            {
                var em = new DuzenlenenMesh(mf, topH[mf]);
                // 1) split large triangles in the region down to <= 1 m (the regrade must not poke through the new asphalt)
                em.Subdivide((wa, wb, wc) =>
                {
                    var cen = (wa + wb + wc) / 3f;
                    bool inBox = box.Contains(wa) || box.Contains(wb) || box.Contains(wc) || box.Contains(cen);
                    return inBox && (Relevant(wa, wb) || Relevant(wb, wc) || Relevant(wc, wa) || Relevant(cen, cen));
                });
                nSplit += em.nSplit;

                // 2) regrade
                var pos = em.pos; var top = em.top;
                var changed = new bool[pos.Count]; int nch = 0;
                for (int v = 0; v < pos.Count; v++)
                {
                    var w = em.W(v);
                    if (!box.Contains(w)) continue;
                    var ros = UnityToRos(w);
                    if (!g.Zemin(ros.x, ros.y, out var hz, out var wt)) continue;
                    float wc = Mathf.Clamp01(wt);
                    float ny = w.y < top[v] - 0.05f ? w.y + wc * (hz - top[v])       // below the surface: move with it
                                                     : Mathf.Lerp(w.y, hz, wc);       // surface (and curb top): pull to target
                    if (w.y < top[v] - 0.05f) nSkirt++;
                    if (Mathf.Abs(ny - w.y) < 1e-4f) continue;
                    w.y = ny; em.SetW(v, w); changed[v] = true; nch++;
                }

                // 3) sub-meshes: old loop -> grass; old markings -> grass / asphalt (RoadRunner markings sit in holes cut
                //    into the asphalt, deleting them would leave holes); curb / gutter / sidewalk inside the new road -> asphalt
                var mr = em.mr; var mats = mr.sharedMaterials.ToList(); var tris = em.tris;
                int grassIdx = mats.FindIndex(m => m != null && m.name.IndexOf("Grass", StringComparison.OrdinalIgnoreCase) >= 0);
                int asphIdx = mats.FindIndex(m => m != null && m.name.IndexOf("Asphalt", StringComparison.OrdinalIgnoreCase) >= 0);
                var toGrass = new List<int>(); var toAsph = new List<int>(); int movedHere = 0, delHere = 0, curbHere = 0;
                for (int s = 0; s < tris.Length && s < mats.Count; s++)
                {
                    var nm = mats[s] != null ? mats[s].name : "";
                    bool road = IsRoadLikeMat(nm), mark = IsMarkingMat(nm);
                    bool edge = road && nm.IndexOf("Asphalt", StringComparison.OrdinalIgnoreCase) < 0 && nm.IndexOf("Concrete1_Road", StringComparison.OrdinalIgnoreCase) < 0;
                    if (!road && !mark) continue;
                    var keep = new List<int>(tris[s].Count); var t = tris[s];
                    for (int k = 0; k + 2 < t.Count; k += 3)
                    {
                        var c = em.l2w.MultiplyPoint3x4((pos[t[k]] + pos[t[k + 1]] + pos[t[k + 2]]) / 3f);
                        var ros = UnityToRos(c);
                        bool inCim = g.Maske(g.cim, ros.x, ros.y), inSil = g.Maske(g.sil, ros.x, ros.y);
                        if (mark && inCim) { toGrass.Add(t[k]); toGrass.Add(t[k + 1]); toGrass.Add(t[k + 2]); delHere++; continue; }
                        if (mark && inSil) { toAsph.Add(t[k]); toAsph.Add(t[k + 1]); toAsph.Add(t[k + 2]); delHere++; continue; }
                        if (road && inCim) { toGrass.Add(t[k]); toGrass.Add(t[k + 1]); toGrass.Add(t[k + 2]); movedHere++; continue; }
                        if (edge && inSil) { toAsph.Add(t[k]); toAsph.Add(t[k + 1]); toAsph.Add(t[k + 2]); curbHere++; continue; }
                        keep.Add(t[k]); keep.Add(t[k + 1]); keep.Add(t[k + 2]);
                    }
                    tris[s] = keep;
                }
                if (nch == 0 && movedHere == 0 && delHere == 0 && curbHere == 0 && em.nSplit == 0) continue;
                em.AddTo(mats, ref grassIdx, matGrass, toGrass);
                em.AddTo(mats, ref asphIdx, matAsphalt, toAsph);
                em.Commit("_nizamiye", nch > 0 ? changed : null, mats);
                nMesh++; nVert += nch; nGrass += movedHere; nMarkDel += delHere; nCurb += curbHere;
            }
            L($"Nizamiye: {nMesh} mesh düzenlendi: {nSplit} üçgen bölündü (kenar <= 1 m), {nVert} köşe yeniden yüksekliklendi ({nSkirt} yüzey altı köşe yüzeyle birlikte kaydırıldı) (yol seviyesi + 8 m şev), {nGrass} eski yol üçgeni çime, {nCurb} bordür/oluk/kaldırım üçgeni asfalta, {nMarkDel} eski çizgi üçgeni asfalta/çime çevrildi");

            // new asphalt and markings (world frame; independent of the model root's rotation)
            MakeOverlayMesh("Nizamiye_Asfalt", d.asfalt_v, d.asfalt_t, model.transform, matAsphalt, true);
            var cz = matMark != null ? MakeOverlayMesh("Nizamiye_Cizgiler", d.cizgi_v, d.cizgi_t, model.transform, matMark, false) : null;
            var matMarkY = FindModelMaterial(model, n => IsMarkingMat(n) && n.IndexOf("Yellow", StringComparison.OrdinalIgnoreCase) >= 0);
            if (matMarkY != null && d.cizgi_sari_v != null && d.cizgi_sari_v.Length > 0)
                MakeOverlayMesh("Nizamiye_Cizgiler_Sari", d.cizgi_sari_v, d.cizgi_sari_t, model.transform, matMarkY, false);
            Physics.SyncTransforms();

            L($"Nizamiye: yeni asfalt {d.asfalt_t.Length / 3} üçgen, çizgi {(cz != null ? d.cizgi_t.Length / 3 : 0)} beyaz + {(matMarkY != null && d.cizgi_sari_t != null ? d.cizgi_sari_t.Length / 3 : 0)} sarı üçgen" +
              (matMark == null ? " (çizgi malzemesi yok!)" : ""));

            // the bus shelter is added in ApplyDuzenlemeler after the islands, so it stands on the sidewalk (not 20 cm into it)
        }

        // Flat overlay mesh from ROS triangles; faces are turned up (clockwise in Unity), optional MeshCollider.
        static GameObject MakeOverlayMesh(string name, float[] v, int[] t, Transform parent, Material mat, bool collider)
        {
            int n = v.Length / 3;
            var pos = new Vector3[n]; var uv = new Vector2[n];
            for (int i = 0; i < n; i++) { pos[i] = RosToUnity(new Vector3(v[3 * i], v[3 * i + 1], v[3 * i + 2])); uv[i] = new Vector2(v[3 * i], v[3 * i + 1]); }
            var tri = (int[])t.Clone();
            for (int k = 0; k + 2 < tri.Length; k += 3)
                if (Vector3.Cross(pos[tri[k + 1]] - pos[tri[k]], pos[tri[k + 2]] - pos[tri[k]]).y < 0f) { var s = tri[k + 1]; tri[k + 1] = tri[k + 2]; tri[k + 2] = s; }
            var mesh = new Mesh { name = name, indexFormat = UnityEngine.Rendering.IndexFormat.UInt32 };
            mesh.vertices = pos; mesh.uv = uv; mesh.triangles = tri;
            mesh.RecalculateNormals(); mesh.RecalculateTangents(); mesh.RecalculateBounds();
            var go = new GameObject(name);
            go.transform.SetPositionAndRotation(Vector3.zero, Quaternion.identity);
            go.transform.SetParent(parent, true);
            go.AddComponent<MeshFilter>().sharedMesh = mesh;
            var mr = go.AddComponent<MeshRenderer>(); mr.sharedMaterial = mat;
            if (collider) go.AddComponent<MeshCollider>().sharedMesh = mesh;
            return go;
        }

        // Simple bus shelter: roof, back and side glass, posts, bench. The open side faces the road (east).
        static void AddBusStop(NizamiyeDurak s, Transform parent)
        {
            var mats = BuildingMaterials();
            float th = s.yaw_deg * Mathf.Deg2Rad;
            var front = RosToUnity(new Vector3(Mathf.Sin(th), -Mathf.Cos(th), 0f)).normalized;   // right normal of the lane: east
            var p = RosToUnity(new Vector3(s.x, s.y, s.z));
            if (Physics.Raycast(p + Vector3.up * 5f, Vector3.down, out var hit, 10f)) p.y = hit.point.y;
            var root = new GameObject("Nizamiye_Durak");
            root.transform.SetParent(parent, false);
            root.transform.SetPositionAndRotation(p, Quaternion.LookRotation(front, Vector3.up));   // local +z = road side, +x = along the road
            void Part(string n, Vector3 c, Vector3 sz, Material m)
            {
                var b = GameObject.CreatePrimitive(PrimitiveType.Cube); b.name = n;
                b.transform.SetParent(root.transform, false); b.transform.localPosition = c; b.transform.localScale = sz;
                if (m != null) b.GetComponent<MeshRenderer>().sharedMaterial = m;
            }
            const float L_ = 4.0f, D = 1.6f, H = 2.5f;
            Part("Cati", new Vector3(0f, H + 0.05f, 0f), new Vector3(L_ + 0.3f, 0.1f, D + 0.3f), mats.cati);
            Part("ArkaCam", new Vector3(0f, H / 2f + 0.05f, -D / 2f), new Vector3(L_, H - 0.2f, 0.04f), mats.cam);
            Part("YanCam_1", new Vector3(-L_ / 2f, H / 2f + 0.05f, -D / 4f), new Vector3(0.04f, H - 0.2f, D / 2f), mats.cam);
            Part("YanCam_2", new Vector3(L_ / 2f, H / 2f + 0.05f, -D / 4f), new Vector3(0.04f, H - 0.2f, D / 2f), mats.cam);
            foreach (var sx in new[] { -1f, 1f })
                foreach (var sz in new[] { -1f, 1f })
                    Part("Dikme", new Vector3(sx * L_ / 2f, H / 2f, sz * D / 2f), new Vector3(0.08f, H, 0.08f), mats.detay);
            Part("Oturak", new Vector3(0f, 0.45f, -D / 2f + 0.3f), new Vector3(L_ * 0.75f, 0.06f, 0.4f), mats.detay);
            L($"Nizamiye: otobüs durağı kulübesi ROS ({s.x:F1}, {s.y:F1}), yön {s.yaw_deg:F0}°");
        }

        // ================= gate objects (nesneler) =================
        // Every object is built from simple parts, then merged into ONE readable mesh with a MeshCollider (RGL lidar, physics,
        // point-cloud export). Names start with "Nizamiye_N_", so FixTrees hides a tree that stands in a wall or fence.
        // Objects stand on the surface under them (raycast); heights in the data are above that surface.
        const string GatePrefix = "Nizamiye_N_";

        static float GateGround(float rx, float ry)   // Unity y of the highest surface at ROS (x, y), gate objects ignored
        {
            var p = RosToUnity(new Vector3(rx, ry, 0f)); float best = float.NaN;
            foreach (var h in Physics.RaycastAll(new Vector3(p.x, 400f, p.z), Vector3.down, 800f, ~0, QueryTriggerInteraction.Ignore))
            {
                if (h.collider.name.StartsWith(GatePrefix)) continue;
                if (h.collider.transform.parent != null && h.collider.transform.parent.name == "Nizamiye_Durak") continue;   // bus shelter roof is not ground
                if (float.IsNaN(best) || h.point.y > best) best = h.point.y;
            }
            return best;
        }

        // lowest surface under a rectangle (centre, corners, edge midpoints); ax / ay = unit axes in ROS, hx / hy = half sizes
        static float GateGroundMin(Vector2 c, Vector2 ax, Vector2 ay, float hx, float hy)
        {
            float m = float.NaN;
            for (int i = -1; i <= 1; i++)
                for (int j = -1; j <= 1; j++)
                {
                    var q = c + ax * (i * hx) + ay * (j * hy); float g = GateGround(q.x, q.y);
                    if (!float.IsNaN(g) && (float.IsNaN(m) || g < m)) m = g;
                }
            return m;
        }

        static Vector3 RosDir(Vector2 d) { var u = RosToUnity(new Vector3(d.x, d.y, 0f)); u.y = 0f; return u.normalized; }
        static Vector3 RosAt(Vector2 p, float unityY) { var u = RosToUnity(new Vector3(p.x, p.y, 0f)); u.y = unityY; return u; }

        static void GPrim(PrimitiveType t, Transform p, Vector3 pos, Quaternion rot, Vector3 sc, Material m)
        {
            var g = GameObject.CreatePrimitive(t); UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());
            g.transform.SetParent(p, false); g.transform.SetPositionAndRotation(pos, rot); g.transform.localScale = sc;
            g.GetComponent<MeshRenderer>().sharedMaterial = m;
        }
        static void GRod(Transform p, Vector3 a, Vector3 b, float r, Material m)
            => GPrim(PrimitiveType.Cylinder, p, (a + b) / 2f, Quaternion.FromToRotation(Vector3.up, (b - a).normalized),
                     new Vector3(2f * r, (b - a).magnitude / 2f, 2f * r), m);
        // box whose centre line runs from a to b (may slope); w = width across, h = height
        static void GBeam(Transform p, Vector3 a, Vector3 b, float w, float h, Material m)
            => GPrim(PrimitiveType.Cube, p, (a + b) / 2f, Quaternion.LookRotation((b - a).normalized, Vector3.up), new Vector3(w, h, (b - a).magnitude), m);
        // box in a local frame: c = centre, f = horizontal facing direction (local +z), size (x across, y up, z along f)
        static void GBox(Transform p, Vector3 c, Vector3 f, Vector3 size, Material m)
            => GPrim(PrimitiveType.Cube, p, c, Quaternion.LookRotation(f, Vector3.up), size, m);

        // two-sided strip: column i goes from bot[i] to top[i]; uv = (u[i], height) * uvScale
        static void GStrip(Transform p, List<Vector3> bot, List<Vector3> top, List<float> u, Material m, Vector2 uvScale)
        {
            int n = bot.Count; var vs = new List<Vector3>(); var uv = new List<Vector2>(); var tr = new List<int>();
            for (int side = 0; side < 2; side++)
            {
                int o = vs.Count;
                for (int i = 0; i < n; i++)
                {
                    vs.Add(bot[i]); vs.Add(top[i]);
                    uv.Add(new Vector2(u[i] * uvScale.x, 0f)); uv.Add(new Vector2(u[i] * uvScale.x, (top[i] - bot[i]).magnitude * uvScale.y));
                }
                for (int i = 0; i + 1 < n; i++)
                {
                    int a = o + 2 * i, b = a + 1, c = a + 2, d = a + 3;
                    if (side == 0) tr.AddRange(new[] { a, b, c, b, d, c }); else tr.AddRange(new[] { a, c, b, b, c, d });
                }
            }
            var mesh = new Mesh { name = "serit", indexFormat = UnityEngine.Rendering.IndexFormat.UInt32 };
            mesh.SetVertices(vs); mesh.SetUVs(0, uv); mesh.SetTriangles(tr, 0); mesh.RecalculateNormals(); mesh.RecalculateBounds();
            var g = new GameObject("serit"); g.transform.SetParent(p, false);
            g.AddComponent<MeshFilter>().sharedMesh = mesh; g.AddComponent<MeshRenderer>().sharedMaterial = m;
        }

        // merge the parts under root into one mesh (one submesh per material) + MeshCollider
        static void GMerge(GameObject root, string name)
        {
            var parts = root.GetComponentsInChildren<MeshFilter>(true);
            var w2l = root.transform.worldToLocalMatrix; var subs = new List<CombineInstance>(); var mats = new List<Material>();
            foreach (var grp in parts.GroupBy(f => f.GetComponent<MeshRenderer>().sharedMaterial))
            {
                var m = new Mesh { indexFormat = UnityEngine.Rendering.IndexFormat.UInt32 };
                m.CombineMeshes(grp.Select(f => new CombineInstance { mesh = f.sharedMesh, transform = w2l * f.transform.localToWorldMatrix }).ToArray(), true, true);
                subs.Add(new CombineInstance { mesh = m, transform = Matrix4x4.identity }); mats.Add(grp.Key);
            }
            var mesh = new Mesh { name = name, indexFormat = UnityEngine.Rendering.IndexFormat.UInt32 };
            mesh.CombineMeshes(subs.ToArray(), false, false); mesh.RecalculateBounds();
            foreach (var s in subs) UnityEngine.Object.DestroyImmediate(s.mesh);
            foreach (var f in parts) UnityEngine.Object.DestroyImmediate(f.gameObject);
            root.name = name;
            root.AddComponent<MeshFilter>().sharedMesh = mesh;
            root.AddComponent<MeshRenderer>().sharedMaterials = mats.ToArray();
            root.AddComponent<MeshCollider>().sharedMesh = mesh;
        }

        static Material GateMat(string name, Color c, float smooth, float metal, Texture2D tex = null, bool cutout = false)
        {
            var shader = Shader.Find("HDRP/Lit"); var path = $"{MatDir}/Nizamiye_{name}.mat";
            var m = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (m == null) { m = new Material(shader); AssetDatabase.CreateAsset(m, path); }
            m.shader = shader;
            m.SetTexture("_BaseColorMap", tex); m.SetTexture("_NormalMap", null); m.SetTexture("_MaskMap", null);
            m.SetTextureScale("_BaseColorMap", Vector2.one); m.SetTextureOffset("_BaseColorMap", Vector2.zero);
            m.SetColor("_BaseColor", c); m.SetFloat("_Metallic", metal); m.SetFloat("_Smoothness", smooth);
            m.SetFloat("_AlphaCutoffEnable", cutout ? 1f : 0f); m.SetFloat("_AlphaCutoff", 0.5f);
            m.SetFloat("_DoubleSidedEnable", cutout ? 1f : 0f);
            ResetHdrpKeywords(m); EditorUtility.SetDirty(m); return m;
        }

        // texture drawn by a function of (u, v) in 0..1 (v = 0 at the bottom), saved as a PNG asset
        static Texture2D GateTex(string name, int w, int h, Func<float, float, Color> f, bool alpha, bool repeat)
        {
            var path = $"{TexDir}/Nizamiye_{name}.png";
            var t = new Texture2D(w, h, TextureFormat.RGBA32, false); var px = new Color[w * h];
            for (int j = 0; j < h; j++) for (int i = 0; i < w; i++) px[j * w + i] = f((i + 0.5f) / w, (j + 0.5f) / h);
            t.SetPixels(px); t.Apply();
            File.WriteAllBytes(path, t.EncodeToPNG()); UnityEngine.Object.DestroyImmediate(t);
            AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceSynchronousImport);
            var imp = (TextureImporter)AssetImporter.GetAtPath(path);
            imp.textureType = TextureImporterType.Default; imp.sRGBTexture = true; imp.alphaIsTransparency = alpha;
            imp.mipMapsPreserveCoverage = alpha; imp.alphaTestReferenceValue = 0.5f;
            imp.wrapMode = repeat ? TextureWrapMode.Repeat : TextureWrapMode.Clamp; imp.SaveAndReimport();
            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }

        static float Hash01(int a, int b) { unchecked { uint h = (uint)(a * 73856093) ^ (uint)(b * 19349663); h ^= h >> 13; h *= 0x5bd1e995; h ^= h >> 15; return (h & 0xffff) / 65535f; } }
        static float SegDist(Vector2 p, Vector2 a, Vector2 b) { var ab = b - a; float t = Mathf.Clamp01(Vector2.Dot(p - a, ab) / Mathf.Max(ab.sqrMagnitude, 1e-9f)); return (p - (a + t * ab)).magnitude; }
        static bool InStar(Vector2 p, Vector2 c, float R, float startDeg)
        {
            var poly = new List<Vector2>();
            for (int k = 0; k < 10; k++) { float a = (startDeg + 36f * k) * Mathf.Deg2Rad; float r = k % 2 == 0 ? R : R * 0.382f; poly.Add(c + r * new Vector2(Mathf.Cos(a), Mathf.Sin(a))); }
            return InPoly(p, poly);
        }

        // flag of Turkey (length 1.5 G): crescent circles at 0.5 G / 0.5625 G from the hoist (diameters 0.5 G / 0.4 G),
        // star (circumscribed diameter 0.25 G, one point towards the hoist) 1/3 G past the inner circle's centre
        static Color FlagTR(float u, float v)
        {
            float X = 1.5f * u, Y = v; var red = new Color(0.89f, 0.04f, 0.09f);
            bool outer = (X - 0.5f) * (X - 0.5f) + (Y - 0.5f) * (Y - 0.5f) <= 0.0625f;
            bool inner = (X - 0.5625f) * (X - 0.5625f) + (Y - 0.5f) * (Y - 0.5f) <= 0.04f;
            if (outer && !inner) return Color.white;
            if (InStar(new Vector2(X, Y), new Vector2(0.5625f + 1f / 3f + 0.125f, 0.5f), 0.125f, 180f)) return Color.white;
            return red;
        }

        // blue pedestrian-crossing sign: white triangle, black walking figure on a zebra
        static Color SignPedestrian(float u, float v)
        {
            var blue = new Color(0.0f, 0.30f, 0.66f); var p = new Vector2(u, v);
            if (u < 0.03f || u > 0.97f || v < 0.03f || v > 0.97f) return Color.white;
            var tri = new List<Vector2> { new Vector2(0.5f, 0.88f), new Vector2(0.12f, 0.15f), new Vector2(0.88f, 0.15f) };
            if (!InPoly(p, tri)) return blue;
            if (v < 0.25f && v > 0.18f && Mathf.FloorToInt(u * 14f) % 2 == 0) return Color.black;   // zebra
            bool body = (p - new Vector2(0.52f, 0.66f)).magnitude < 0.045f
                        || SegDist(p, new Vector2(0.51f, 0.60f), new Vector2(0.48f, 0.42f)) < 0.028f
                        || SegDist(p, new Vector2(0.48f, 0.42f), new Vector2(0.40f, 0.27f)) < 0.022f
                        || SegDist(p, new Vector2(0.48f, 0.42f), new Vector2(0.57f, 0.27f)) < 0.022f
                        || SegDist(p, new Vector2(0.50f, 0.56f), new Vector2(0.41f, 0.46f)) < 0.018f
                        || SegDist(p, new Vector2(0.50f, 0.56f), new Vector2(0.59f, 0.49f)) < 0.018f;
            return body ? Color.black : Color.white;
        }

        // wire mesh, 1 m x 1 m tile (diamonds of ~6 cm), alpha = wire
        static Color FenceMesh(float u, float v)
        {
            float a = (u + v) * 12f, b = (u - v) * 12f; a -= Mathf.Floor(a); b -= Mathf.Floor(b);
            bool wire = a < 0.07f || a > 0.93f || b < 0.07f || b > 0.93f;
            return new Color(0.70f, 0.75f, 0.70f, wire ? 1f : 0f);
        }

        // cut-stone blocks, 2 m x 1 m tile: 0.5 x 0.25 m blocks, staggered rows, light mortar joints
        static Color StoneBlocks(float u, float v)
        {
            float x = 2f * u, y = v; int row = Mathf.FloorToInt(y / 0.25f); float xs = x + (row % 2 == 1 ? 0.25f : 0f);
            int col = Mathf.FloorToInt(xs / 0.5f) % 4; float fx = xs - Mathf.Floor(xs / 0.5f) * 0.5f, fy = y - row * 0.25f;
            if (fx < 0.012f || fy < 0.012f) return new Color(0.80f, 0.78f, 0.74f);
            float tone = 0.86f + 0.22f * Hash01(row, col) + 0.04f * (Hash01((int)(x * 300f), (int)(y * 300f)) - 0.5f);
            return new Color(0.70f * tone, 0.66f * tone, 0.58f * tone);
        }

        // polished red granite cladding, 1.2 m x 1.2 m tile (0.6 m plates, dark joints, speckles)
        static Color Granite(float u, float v)
        {
            float a = u * 2f, b = v * 2f; int pi = Mathf.FloorToInt(a), pj = Mathf.FloorToInt(b);
            if (a - pi < 0.012f || b - pj < 0.012f) return new Color(0.50f, 0.34f, 0.31f);
            float tone = 0.93f + 0.14f * Hash01(pi + 7, pj + 3);
            float sp = Hash01((int)(u * 512f), (int)(v * 512f)); float k = sp > 0.93f ? 0.55f : sp < 0.06f ? 1.25f : 0.92f + 0.16f * sp;
            return new Color(Mathf.Min(1f, 0.80f * tone * k), 0.52f * tone * k, 0.45f * tone * k);
        }

        // patinated copper fascia, 2 m x 1 m tile: 0.5 m panels with dark ribs, green / brown streaks
        static Color CopperFascia(float u, float v)
        {
            float a = u * 4f; int pi = Mathf.FloorToInt(a); float f = a - pi;
            if (f < 0.05f) return new Color(0.18f, 0.20f, 0.17f);
            float st = Hash01((int)(u * 160f), 11) * 0.6f + Hash01(pi, 5) * 0.4f;   // vertical streaks + panel tone
            float g = Mathf.Lerp(0.0f, 1.0f, st) * (0.8f + 0.2f * v);
            var green = new Color(0.38f, 0.50f, 0.42f); var brown = new Color(0.40f, 0.33f, 0.24f);
            return Color.Lerp(brown, green, g) * (0.9f + 0.2f * Hash01((int)(u * 400f), (int)(v * 200f)));
        }

        // plan outline of the booth (body or roof): rectangle from v = vs to the arc centre va, semicircle of radius r around (0, va)
        static List<Vector2> BoothOutline(float r, float vs, float va, int nArc)
        {
            var l = new List<Vector2> { new Vector2(r, vs) };
            for (int k = 0; k <= nArc; k++) { float t = Mathf.PI * k / nArc; l.Add(new Vector2(r * Mathf.Cos(t), va + r * Mathf.Sin(t))); }
            l.Add(new Vector2(-r, vs));
            return l;   // counter-clockwise (east side first), open: the last point connects back to the first
        }

        static void AddBigBooth(Transform gate, BuyukKulube k, Material mDark, Material mWhite, (Material duvar, Material cati, Material cam, Material detay) bm,
                                ref int nObj, ref int miss, List<string> notes)
        {
            float th = k.aci_deg * Mathf.Deg2Rad; var C = new Vector2(k.x, k.y);
            var U = new Vector2(Mathf.Cos(th), Mathf.Sin(th)); var V = new Vector2(-Mathf.Sin(th), Mathf.Cos(th));
            Vector2 W(float u, float v) => C + U * u + V * v;                       // local (u, v) -> ROS xy
            float a = k.yari_en, vs = k.guney_v, va = k.yay_v;
            float g = GateGroundMin(W(0f, (vs + va) / 2f), U, V, a * 0.6f, (va - vs) * 0.4f);
            if (float.IsNaN(g)) { miss++; notes.Add("büyük kulübe " + k.ad); return; }
            float Hs = k.tavan > 0f ? k.tavan : 3.0f, Ht = k.sacak_ust > 0f ? k.sacak_ust : 4.1f;
            var up = Vector3.up; Vector3 P(float u, float v, float z) => RosAt(W(u, v), g + z);
            Vector3 Dir(float du, float dv) => RosDir(U * du + V * dv);
            var mGran = GateMat("Granit", Color.white, 0.32f, 0f, GateTex("Granit", 512, 512, Granite, false, true));   // low smoothness: a polished face mirrors the blue sky (looked purple)
            var mCopper = GateMat("BakirSacak", Color.white, 0.3f, 0.1f, GateTex("BakirSacak", 512, 256, CopperFascia, false, true));
            var mSoffit = GateMat("Sacakalti", new Color(0.92f, 0.92f, 0.90f), 0.3f, 0f);
            var o = new GameObject("parca"); o.transform.SetParent(gate, false);

            // body: granite walls around the outline, dark plinth at the bottom
            var body = BoothOutline(a, vs, va, 24); body.Add(body[0]);
            var bb = new List<Vector3>(); var bt = new List<Vector3>(); var us = new List<float>(); float sAcc = 0f;
            for (int i = 0; i < body.Count; i++)
            {
                if (i > 0) sAcc += (body[i] - body[i - 1]).magnitude;
                var q = body[i];
                bb.Add(P(q.x, q.y, -0.4f)); bt.Add(P(q.x, q.y, Hs)); us.Add(sAcc);
            }
            GStrip(o.transform, bb, bt, us, mGran, new Vector2(1f / 1.2f, 1f / 1.2f));
            // plinth: 2 cm proud of the wall
            var pl = BoothOutline(a + 0.02f, vs - 0.02f, va, 24); pl.Add(pl[0]);
            GStrip(o.transform, pl.Select(q => P(q.x, q.y, -0.05f)).ToList(), pl.Select(q => P(q.x, q.y, 0.14f)).ToList(), us, mDark, Vector2.one);

            // roof slab (white soffit under, grey top) + patinated copper fascia leaning 8 cm outwards
            float ro = a + (k.tasma > 0f ? k.tasma : 1.4f), rs = vs - (k.tasma_guney > 0f ? k.tasma_guney : 1.7f);
            var roof = BoothOutline(ro, rs, va, 32);
            var cen = W(0f, (rs + va + ro) / 2f);
            void Fan(float z, Material m, bool faceUp)
            {
                var vs_ = new List<Vector3> { RosAt(cen, g + z) }; var tr = new List<int>();
                foreach (var q in roof) vs_.Add(P(q.x, q.y, z));
                for (int i = 1; i <= roof.Count; i++)
                {
                    int j = i % roof.Count + 1;
                    if (faceUp) tr.AddRange(new[] { 0, j, i }); else tr.AddRange(new[] { 0, i, j });
                }
                var mesh = new Mesh { name = "cati", indexFormat = UnityEngine.Rendering.IndexFormat.UInt32 };
                mesh.SetVertices(vs_); mesh.SetTriangles(tr, 0); mesh.RecalculateNormals();
                if (faceUp != (mesh.normals[0].y > 0f)) { tr.Reverse(); mesh.SetTriangles(tr, 0); mesh.RecalculateNormals(); }
                mesh.SetUVs(0, vs_.Select(w => new Vector2(w.x, w.z)).ToList()); mesh.RecalculateBounds();
                var go = new GameObject("cati"); go.transform.SetParent(o.transform, false);
                go.AddComponent<MeshFilter>().sharedMesh = mesh; go.AddComponent<MeshRenderer>().sharedMaterial = m;
            }
            Fan(Hs, mSoffit, false); Fan(Hs + 0.25f, bm.cati, true);
            var rl = new List<Vector2>(roof) { roof[0] };
            var rus = new List<float> { 0f }; for (int i = 1; i < rl.Count; i++) rus.Add(rus[i - 1] + (rl[i] - rl[i - 1]).magnitude);
            GStrip(o.transform, rl.Select(q => P(q.x, q.y, Hs)).ToList(), rl.Select(q => P(q.x, q.y, Hs + 0.25f)).ToList(), rus, mSoffit, Vector2.one);
            Vector2 Out(Vector2 q) => q.y > va ? new Vector2(q.x, q.y - va).normalized : (Mathf.Abs(q.x) >= ro - 1e-3f && q.y > rs + 1e-3f ? new Vector2(Mathf.Sign(q.x), 0f) : q.y <= rs + 1e-3f && Mathf.Abs(q.x) < ro - 1e-3f ? new Vector2(0f, -1f) : new Vector2(Mathf.Sign(q.x), -1f).normalized);
            GStrip(o.transform, rl.Select(q => P(q.x, q.y, Hs + 0.25f)).ToList(), rl.Select(q => { var e = q + Out(q) * 0.08f; return P(e.x, e.y, Ht); }).ToList(),
                   rus, mCopper, new Vector2(0.5f, 1f));

            // openings
            int nOpen = 0;
            foreach (var w in k.acikliklar ?? new KulubeAciklik[0])
            {
                float z0 = w.alt, z1 = w.ust, zc = (z0 + z1) / 2f, hh = z1 - z0;
                if (w.yuz == "yay")
                {
                    int ns = Mathf.Max(1, Mathf.RoundToInt((w.s1 - w.s0) / 7.5f));
                    for (int i = 0; i < ns; i++)
                    {
                        float t0 = (w.s0 + (w.s1 - w.s0) * i / ns) * Mathf.Deg2Rad, t1 = (w.s0 + (w.s1 - w.s0) * (i + 1) / ns) * Mathf.Deg2Rad, tm = (t0 + t1) / 2f;
                        var nrm = new Vector2(Mathf.Cos(tm), Mathf.Sin(tm)); float chord = 2f * a * Mathf.Sin((t1 - t0) / 2f);
                        var F = Dir(nrm.x, nrm.y); var c0 = new Vector2(0f, va) + nrm * (a * Mathf.Cos((t1 - t0) / 2f));
                        GBox(o.transform, P(c0.x + nrm.x * 0.03f, c0.y + nrm.y * 0.03f, zc), F, new Vector3(chord, hh, 0.05f), bm.cam);
                        foreach (var zz in new[] { z0 - 0.04f, z1 + 0.04f })
                            GBox(o.transform, P(c0.x + nrm.x * 0.04f, c0.y + nrm.y * 0.04f, zz), F, new Vector3(chord + 0.02f, 0.08f, 0.06f), mWhite);
                        var e0 = new Vector2(0f, va) + new Vector2(Mathf.Cos(t0), Mathf.Sin(t0)) * (a + 0.04f);
                        GBox(o.transform, P(e0.x, e0.y, zc), F, new Vector3(0.07f, hh, 0.06f), mWhite);
                        if (i == ns - 1) { var e1 = new Vector2(0f, va) + new Vector2(Mathf.Cos(t1), Mathf.Sin(t1)) * (a + 0.04f); GBox(o.transform, P(e1.x, e1.y, zc), F, new Vector3(0.07f, hh, 0.06f), mWhite); }
                    }
                    nOpen++; continue;
                }
                // straight faces: centre point on the face, outward normal
                Vector2 c; Vector2 nr; float wd = w.s1 - w.s0, sm = (w.s0 + w.s1) / 2f;
                if (w.yuz == "dogu") { c = new Vector2(a, vs + sm); nr = new Vector2(1f, 0f); }
                else if (w.yuz == "bati") { c = new Vector2(-a, vs + sm); nr = new Vector2(-1f, 0f); }
                else { c = new Vector2(-a + sm, vs); nr = new Vector2(0f, -1f); }
                var Fo = Dir(nr.x, nr.y);
                Vector3 At(float off, float z) => P(c.x + nr.x * off, c.y + nr.y * off, z);
                if (w.tur == "boru")          // dark downpipe, 12 cm off the wall
                {
                    GRod(o.transform, At(0.12f, 0f), At(0.12f, Hs), 0.05f, mDark); nOpen++; continue;
                }
                if (w.tur == "pano")          // white board on the wall
                {
                    GBox(o.transform, At(0.03f, zc), Fo, new Vector3(wd, hh, 0.04f), mWhite); nOpen++; continue;
                }
                if (w.tur == "kapi")          // white recessed frame, glass door, kick plate, step
                {
                    GBox(o.transform, At(0.02f, zc), Fo, new Vector3(wd + 0.16f, hh + 0.08f, 0.04f), mWhite);
                    GBox(o.transform, At(0.04f, zc + 0.05f), Fo, new Vector3(wd - 0.3f, hh - 0.25f, 0.03f), bm.cam);
                    GBox(o.transform, At(0.045f, 0.18f), Fo, new Vector3(wd - 0.3f, 0.3f, 0.02f), mWhite);
                    GBox(o.transform, At(0.35f, -0.05f), Fo, new Vector3(wd + 0.3f, 0.2f, 0.6f), bm.detay);
                    nOpen++; continue;
                }
                GBox(o.transform, At(0.02f, zc), Fo, new Vector3(wd + 0.1f, hh + 0.1f, 0.04f), mWhite);        // window frame
                GBox(o.transform, At(0.035f, zc), Fo, new Vector3(wd - 0.06f, hh - 0.06f, 0.03f), bm.cam);       // glass
                if (wd > 1.2f) GBox(o.transform, At(0.05f, zc), Fo, new Vector3(0.06f, hh - 0.06f, 0.02f), mWhite);   // mullion
                if (hh > 1.0f) GBox(o.transform, At(0.05f, z0 + hh * 0.38f), Fo, new Vector3(wd - 0.06f, 0.06f, 0.02f), mWhite);  // transom
                nOpen++;
            }

            // security cameras under the soffit: south-east and south-west corners, north-east and north-west on the arc
            foreach (var (cu, cv) in new[] { (a + 0.45f, vs - 0.3f), (-a - 0.45f, vs - 0.3f), (a * 0.8f + 0.45f, va + a * 0.75f), (-a * 0.8f - 0.45f, va + a * 0.75f) })
            {
                var F = Dir(Mathf.Sign(cu), cv < vs ? -1f : 1f);
                GBox(o.transform, P(cu, cv, Hs - 0.08f), F, new Vector3(0.06f, 0.16f, 0.06f), mWhite);
                GBox(o.transform, P(cu, cv, Hs - 0.22f), F, new Vector3(0.12f, 0.12f, 0.28f), mWhite);
            }
            GMerge(o, GatePrefix + "BuyukKulube_" + k.ad); nObj++;
            if (!string.IsNullOrEmpty(k.osm_id)) GateReplacedBuildings.Add(k.osm_id);
            L($"Nizamiye: büyük kulübe {k.ad}: gövde {2f * a:F1} x {va - vs + a:F1} m, çatı {2f * ro:F1} m, {nOpen} açıklık; OSM binası {k.osm_id} yerine");
        }

        static void AddGateObjects(Transform parent, NesneVeri n)
        {
            Physics.SyncTransforms();
            // the root stays at the world origin (the Models node inherited from the Shinjuku scene has its own transform);
            // strips are built from world vertices, so every part must sit under a world-identity root
            var gate = new GameObject("Nizamiye_Nesneler").transform;
            gate.SetPositionAndRotation(Vector3.zero, Quaternion.identity); gate.SetParent(parent, true);
            var up = Vector3.up; int nObj = 0, miss = 0; var notes = new List<string>();
            var bm = BuildingMaterials();
            var mYellow = GateMat("Sari", new Color(0.95f, 0.74f, 0.05f), 0.45f, 0f);
            var mDark = GateMat("Koyu", new Color(0.12f, 0.12f, 0.12f), 0.3f, 0f);
            var mRed = GateMat("Kirmizi", new Color(0.80f, 0.07f, 0.07f), 0.45f, 0f);
            var mWhite = GateMat("Beyaz", new Color(0.93f, 0.93f, 0.92f), 0.45f, 0f);
            var mPole = GateMat("Direk", new Color(0.86f, 0.86f, 0.86f), 0.6f, 0.5f);
            var mSteel = GateMat("Celik", new Color(0.70f, 0.72f, 0.74f), 0.5f, 0.7f);
            var mFencePost = GateMat("CitDirek", new Color(0.30f, 0.36f, 0.30f), 0.35f, 0.3f);
            GameObject NewObj() { var g = new GameObject("parca"); g.transform.SetParent(gate, false); return g; }

            // entry barriers: yellow post box, red / white arm straight up (the arms are always up at this gate)
            foreach (var b in n.bariyerler ?? new NesneNokta[0])
            {
                float g = GateGroundMin(new Vector2(b.x, b.y), Vector2.right, Vector2.up, 0.16f, 0.16f);
                if (float.IsNaN(g)) { miss++; notes.Add("bariyer " + b.ad); continue; }
                var o = NewObj(); var bp = RosAt(new Vector2(b.x, b.y), g);
                GPrim(PrimitiveType.Cube, o.transform, bp + up * 0.475f, Quaternion.identity, new Vector3(0.32f, 1.05f, 0.32f), mYellow);
                GPrim(PrimitiveType.Cube, o.transform, bp + up * 1.04f, Quaternion.identity, new Vector3(0.36f, 0.08f, 0.36f), mDark);
                float L = b.kol_boy > 0f ? b.kol_boy : 3.8f; int k = Mathf.Max(2, Mathf.RoundToInt(L / 0.45f));
                for (int i = 0; i < k; i++)
                    GRod(o.transform, bp + up * (1.08f + L * i / k), bp + up * (1.08f + L * (i + 1) / k), 0.045f, i % 2 == 0 ? mRed : mWhite);
                GMerge(o, GatePrefix + "Bariyer_" + b.ad); nObj++;
            }

            // flagpoles: white pole, ball on top, a 1.5 x 1.0 m flag near the top flying to the south-east (seen from the road)
            if (NLen(n.bayraklar) > 0)
            {
                var mFlagTR = GateMat("Bayrak_TR", Color.white, 0.2f, 0f, GateTex("Bayrak_TR", 384, 256, FlagTR, false, false));
                var mFlagW = GateMat("Bayrak_Beyaz", new Color(0.96f, 0.96f, 0.96f), 0.2f, 0f);
                foreach (var f in n.bayraklar)
                {
                    float g = GateGround(f.x, f.y);
                    if (float.IsNaN(g)) { miss++; notes.Add("bayrak " + f.ad); continue; }
                    var o = NewObj(); var bp = RosAt(new Vector2(f.x, f.y), g); float H = f.boy > 0f ? f.boy : 8f;
                    GRod(o.transform, bp + up * -0.3f, bp + up * H, 0.05f, mPole);
                    GPrim(PrimitiveType.Sphere, o.transform, bp + up * (H + 0.05f), Quaternion.identity, Vector3.one * 0.14f, mPole);
                    var fly = RosDir(new Vector2(Mathf.Cos(-60f * Mathf.Deg2Rad), Mathf.Sin(-60f * Mathf.Deg2Rad)));
                    var top = bp + up * (H - 0.1f) + fly * 0.06f;
                    GStrip(o.transform, new List<Vector3> { top - up * 1.0f, top - up * 1.0f + fly * 1.5f }, new List<Vector3> { top, top + fly * 1.5f },
                           new List<float> { 0f, 1.5f }, f.bez == "turk" ? mFlagTR : mFlagW, new Vector2(1f / 1.5f, 1f));
                    GMerge(o, GatePrefix + "Bayrak_" + f.ad); nObj++;
                }
            }

            // small guard kiosk: red body, white corner posts / roof / header, window on the front
            foreach (var k in n.kulubeler ?? new NesneNokta[0])
            {
                float W = k.en > 0f ? k.en : 1.6f, D = k.derin > 0f ? k.derin : 1.2f, H = k.boy > 0f ? k.boy : 3.1f;
                var fr = new Vector2(Mathf.Cos(k.yuz_deg * Mathf.Deg2Rad), Mathf.Sin(k.yuz_deg * Mathf.Deg2Rad)); var sd = new Vector2(-fr.y, fr.x);
                float g = GateGroundMin(new Vector2(k.x, k.y), fr, sd, D / 2f, W / 2f);
                if (float.IsNaN(g)) { miss++; notes.Add("kulübe " + k.ad); continue; }
                var o = NewObj(); var c = RosAt(new Vector2(k.x, k.y), g); var F = RosDir(fr); var S = Vector3.Cross(up, F);
                GBox(o.transform, c + up * 0.03f, F, new Vector3(W + 0.1f, 0.16f, D + 0.1f), mWhite);
                GBox(o.transform, c + up * 1.2f, F, new Vector3(W, 2.2f, D), mRed);
                GBox(o.transform, c + up * 1.6f + F * (D / 2f + 0.01f), F, new Vector3(W * 0.7f, 1.0f, 0.03f), bm.cam);
                GBox(o.transform, c + up * 0.98f, F, new Vector3(W + 0.02f, 0.07f, D + 0.02f), mWhite);
                foreach (var sx in new[] { -1f, 1f })
                    foreach (var sz in new[] { -1f, 1f })
                        GBox(o.transform, c + up * 1.2f + S * (sx * W / 2f) + F * (sz * D / 2f), F, new Vector3(0.09f, 2.3f, 0.09f), mWhite);
                GBox(o.transform, c + up * 2.36f, F, new Vector3(W + 0.2f, 0.12f, D + 0.2f), mWhite);
                float hh = Mathf.Max(0.3f, H - 2.42f);
                GBox(o.transform, c + up * (2.42f + hh / 2f) + F * (D / 2f - 0.05f), F, new Vector3(W + 0.1f, hh, 0.12f), mWhite);
                GBox(o.transform, c + up * (2.42f + hh * 0.3f) + F * (D / 2f + 0.015f), F, new Vector3(W * 0.8f, 0.07f, 0.02f), mRed);
                GMerge(o, GatePrefix + "Kulube_" + k.ad); nObj++;
            }

            foreach (var bk in n.buyuk_kulubeler ?? new BuyukKulube[0]) AddBigBooth(gate, bk, mDark, mWhite, bm, ref nObj, ref miss, notes);

            // sign: grey pole, back plate, printed face towards yuz_deg
            if (NLen(n.tabelalar) > 0)
            {
                var mSign = GateMat("Tabela_Yaya", Color.white, 0.4f, 0f, GateTex("Tabela_Yaya", 256, 256, SignPedestrian, false, false));
                var mGrey = GateMat("Gri", new Color(0.62f, 0.63f, 0.64f), 0.4f, 0.4f);
                foreach (var t in n.tabelalar)
                {
                    float g = GateGround(t.x, t.y);
                    if (float.IsNaN(g)) { miss++; notes.Add("tabela " + t.ad); continue; }
                    var o = NewObj(); var bp = RosAt(new Vector2(t.x, t.y), g);
                    float top = t.ust > 0f ? t.ust : 2.5f, sz = t.boyut > 0f ? t.boyut : 0.6f;
                    var fr = new Vector2(Mathf.Cos(t.yuz_deg * Mathf.Deg2Rad), Mathf.Sin(t.yuz_deg * Mathf.Deg2Rad));
                    var F = RosDir(fr); var R = RosDir(new Vector2(-fr.y, fr.x));   // the viewer's right (viewer looks along -F)
                    bool board = t.tur == "beyaz";          // plain white board on two posts (content not copied)
                    if (board) foreach (var sx in new[] { -0.4f, 0.4f }) GRod(o.transform, bp + R * (sx * sz) + up * -0.3f, bp + R * (sx * sz) + up * top, 0.03f, mGrey);
                    else GRod(o.transform, bp + up * -0.3f, bp + up * top, 0.03f, mGrey);
                    var pc = bp + up * (top - sz / 2f) + F * 0.04f;
                    GBox(o.transform, pc, F, new Vector3(sz + 0.02f, sz + 0.02f, 0.02f), mGrey);
                    var fc = pc + F * 0.012f;
                    GStrip(o.transform, new List<Vector3> { fc - R * (sz / 2f) - up * (sz / 2f), fc + R * (sz / 2f) - up * (sz / 2f) },
                           new List<Vector3> { fc - R * (sz / 2f) + up * (sz / 2f), fc + R * (sz / 2f) + up * (sz / 2f) },
                           new List<float> { 0f, sz }, board ? mWhite : mSign, new Vector2(1f / sz, 1f / sz));
                    GMerge(o, GatePrefix + "Tabela_" + t.ad); nObj++;
                }
            }

            // boxes (generator): coloured box on a dark base
            foreach (var b in n.kutular ?? new NesneNokta[0])
            {
                float E = b.en > 0f ? b.en : 1.5f, D = b.derin > 0f ? b.derin : 0.9f, H = b.boy > 0f ? b.boy : 1.3f;
                var ax = new Vector2(Mathf.Cos(b.yon_deg * Mathf.Deg2Rad), Mathf.Sin(b.yon_deg * Mathf.Deg2Rad)); var ay = new Vector2(-ax.y, ax.x);
                float g = GateGroundMin(new Vector2(b.x, b.y), ax, ay, E / 2f, D / 2f);
                if (float.IsNaN(g)) { miss++; notes.Add("kutu " + b.ad); continue; }
                var col = b.renk != null && b.renk.Length >= 3 ? new Color(b.renk[0], b.renk[1], b.renk[2]) : new Color(0.95f, 0.72f, 0.05f);
                var mBox = GateMat("Kutu_" + b.ad, col, 0.45f, 0f);
                var o = NewObj(); var c = RosAt(new Vector2(b.x, b.y), g); var F = RosDir(ay);   // long side along yon_deg
                GBox(o.transform, c + up * 0.05f, F, new Vector3(E, 0.2f, D), mDark);
                GBox(o.transform, c + up * (0.15f + (H - 0.15f) / 2f), F, new Vector3(E - 0.04f, H - 0.15f, D - 0.04f), mBox);
                GBox(o.transform, c + up * (H * 0.55f) + F * (D / 2f - 0.01f), F, new Vector3(E * 0.4f, H * 0.35f, 0.04f), mDark);
                GMerge(o, GatePrefix + "Kutu_" + b.ad); nObj++;
            }

            // banner poles: red pole, two short arms, a coloured banner hanging between them, perpendicular to the road (yon_deg = arm direction)
            if (NLen(n.panolar) > 0)
            {
                var mPoleRed = GateMat("PanoDirek", new Color(0.82f, 0.10f, 0.10f), 0.5f, 0.2f);
                foreach (var b in n.panolar)
                {
                    float g = GateGround(b.x, b.y);
                    if (float.IsNaN(g)) { miss++; notes.Add("pano " + b.ad); continue; }
                    var o = NewObj(); var bp = RosAt(new Vector2(b.x, b.y), g);
                    float H = b.boy > 0f ? b.boy : 5.3f, Wb = b.en > 0f ? b.en : 1.0f, top = b.ust > 0f ? b.ust : 4.7f, Hb = b.boyut > 0f ? b.boyut : 2.6f;
                    var A = RosDir(new Vector2(Mathf.Cos(b.yon_deg * Mathf.Deg2Rad), Mathf.Sin(b.yon_deg * Mathf.Deg2Rad)));
                    GRod(o.transform, bp + up * -0.3f, bp + up * H, 0.06f, mPoleRed);
                    GPrim(PrimitiveType.Sphere, o.transform, bp + up * H, Quaternion.identity, Vector3.one * 0.13f, mPoleRed);
                    foreach (var hy in new[] { top + 0.05f, top - Hb - 0.05f })
                        GRod(o.transform, bp + up * hy, bp + up * hy + A * (Wb + 0.12f), 0.025f, mPoleRed);
                    var col = b.renk != null && b.renk.Length >= 3 ? new Color(b.renk[0], b.renk[1], b.renk[2]) : new Color(0.2f, 0.3f, 0.7f);
                    var mBan = GateMat("Pano_" + b.ad, col, 0.3f, 0f);
                    var b0 = bp + A * 0.1f; var b1 = bp + A * (0.1f + Wb);
                    GStrip(o.transform, new List<Vector3> { b0 + up * (top - Hb), b1 + up * (top - Hb) }, new List<Vector3> { b0 + up * top, b1 + up * top },
                           new List<float> { 0f, Wb }, mBan, Vector2.one);
                    GMerge(o, GatePrefix + "Pano_" + b.ad); nObj++;
                }
            }

            // round (clipped) shrubs and small ornamental trees of the landscaping island
            if (NLen(n.yuvarlak_calilar) > 0)
            {
                var mShrub = GateMat("Cali", new Color(0.17f, 0.34f, 0.13f), 0.2f, 0f);
                foreach (var b in n.yuvarlak_calilar)
                {
                    float g = GateGround(b.x, b.y);
                    if (float.IsNaN(g)) { miss++; notes.Add("çalı " + b.ad); continue; }
                    float D = b.cap > 0f ? b.cap : 1.0f, H = b.boy > 0f ? b.boy : 0.9f;
                    var o = NewObj(); var c = RosAt(new Vector2(b.x, b.y), g);
                    GPrim(PrimitiveType.Sphere, o.transform, c + up * (H / 2f - 0.05f), Quaternion.identity, new Vector3(D, H, D), mShrub);
                    GMerge(o, GatePrefix + "Cali_" + b.ad); nObj++;
                }
            }
            foreach (var b in n.sus_agaclari ?? new NesneNokta[0])
            {
                float g = GateGround(b.x, b.y);
                if (float.IsNaN(g)) { miss++; notes.Add("süs ağacı " + b.ad); continue; }
                float H = b.boy > 0f ? b.boy : 3f, Cw = b.tac > 0f ? b.tac : 1.5f;
                var col = b.renk != null && b.renk.Length >= 3 ? new Color(b.renk[0], b.renk[1], b.renk[2]) : new Color(0.2f, 0.4f, 0.15f);
                var mLeaf = GateMat("SusAgac_" + b.ad, col, 0.2f, 0f); var mBark = GateMat("Govde", new Color(0.30f, 0.22f, 0.15f), 0.15f, 0f);
                var o = NewObj(); var c = RosAt(new Vector2(b.x, b.y), g);
                GRod(o.transform, c + up * -0.2f, c + up * (H - Cw * 0.6f), 0.06f, mBark);
                GPrim(PrimitiveType.Sphere, o.transform, c + up * (H - Cw * 0.45f), Quaternion.identity, new Vector3(Cw, Cw * 0.9f, Cw), mLeaf);
                GMerge(o, GatePrefix + "SusAgac_" + b.ad); nObj++;
            }

            // trash bins: body, slightly wider lid, dark slot
            foreach (var b in n.cop_kutulari ?? new NesneNokta[0])
            {
                float E = b.en > 0f ? b.en : 0.6f, D = b.derin > 0f ? b.derin : 0.6f, H = b.boy > 0f ? b.boy : 1.0f;
                float g = GateGroundMin(new Vector2(b.x, b.y), Vector2.right, Vector2.up, E / 2f, D / 2f);
                if (float.IsNaN(g)) { miss++; notes.Add("çöp kutusu " + b.ad); continue; }
                var col = b.renk != null && b.renk.Length >= 3 ? new Color(b.renk[0], b.renk[1], b.renk[2]) : new Color(0.15f, 0.22f, 0.35f);
                var mBin = GateMat("Cop_" + b.ad, col, 0.35f, 0.1f);
                var o = NewObj(); var c = RosAt(new Vector2(b.x, b.y), g); var F = RosDir(new Vector2(1f, 0f));
                if (b.tur == "beton_silindir")   // concrete cylinder with a thicker rim
                {
                    GPrim(PrimitiveType.Cylinder, o.transform, c + up * (H / 2f - 0.03f), Quaternion.identity, new Vector3(E, H / 2f + 0.03f, E), mBin);
                    GPrim(PrimitiveType.Cylinder, o.transform, c + up * (H - 0.03f), Quaternion.identity, new Vector3(E + 0.06f, 0.04f, E + 0.06f), mBin);
                    GMerge(o, GatePrefix + "Cop_" + b.ad); nObj++; continue;
                }
                GBox(o.transform, c + up * ((H - 0.08f) / 2f - 0.03f), F, new Vector3(E, H - 0.02f, D), mBin);
                GBox(o.transform, c + up * (H - 0.04f), F, new Vector3(E + 0.06f, 0.08f, D + 0.06f), mBin);
                GBox(o.transform, c + up * (H - 0.2f) + F * (D / 2f), F, new Vector3(E * 0.6f, 0.08f, 0.02f), mDark);
                GMerge(o, GatePrefix + "Cop_" + b.ad); nObj++;
            }

            // walls: two faces + top + end caps, sampled every metre; top = road-side ground + height, base sunk under the lowest ground.
            // xy is the road-side FACE (that is what the lidar measures); the wall body lies behind it
            if (NLen(n.duvarlar) > 0)
            {
                var mStone = GateMat("TasDuvar", Color.white, 0.15f, 0f, GateTex("TasDuvar", 512, 256, StoneBlocks, false, true));
                foreach (var w in n.duvarlar)
                {
                    var P = XyList(w.xy); float T = w.kalinlik > 0f ? w.kalinlik : 0.4f;
                    var s0 = new List<float> { 0f }; for (int i = 1; i < P.Count; i++) s0.Add(s0[i - 1] + (P[i] - P[i - 1]).magnitude);
                    float total = s0[s0.Count - 1]; int ns = Mathf.Max(1, Mathf.CeilToInt(total / 1.0f));
                    var rb = new List<Vector3>(); var rt = new List<Vector3>(); var bb = new List<Vector3>(); var bt = new List<Vector3>(); var us = new List<float>();
                    var cb1 = new List<Vector3>(); var ct1 = new List<Vector3>();
                    for (int j = 0; j <= ns; j++)
                    {
                        float s = total * j / ns; int i = 1; while (i < P.Count - 1 && s0[i] < s) i++;
                        float a = Mathf.InverseLerp(s0[i - 1], s0[i], s); var q = Vector2.Lerp(P[i - 1], P[i], a);
                        var d = (P[i] - P[i - 1]).normalized; var nr = new Vector2(d.y, -d.x);     // right of the drawing direction = road side
                        float gRoad = GateGround(q.x + nr.x * 1.2f, q.y + nr.y * 1.2f);
                        q -= nr * (T / 2f);                                                       // centre line, half a thickness behind the face
                        float hgt = w.boy != null && w.boy.Length == P.Count ? Mathf.Lerp(w.boy[i - 1], w.boy[i], a) : 2.5f;
                        float gMin = GateGroundMin(q, d, nr, 0.5f, T / 2f);
                        if (float.IsNaN(gMin)) gMin = gRoad;
                        if (float.IsNaN(gRoad)) gRoad = gMin;
                        if (float.IsNaN(gMin)) { miss++; notes.Add($"duvar {w.ad} s={s:F0}"); gMin = gRoad = rb.Count > 0 ? rb[rb.Count - 1].y + 0.3f : 0f; }
                        float yb = Mathf.Min(gMin, gRoad) - 0.3f, yt = gRoad + hgt;
                        rb.Add(RosAt(q + nr * (T / 2f), yb)); rt.Add(RosAt(q + nr * (T / 2f), yt));
                        bb.Add(RosAt(q - nr * (T / 2f), yb)); bt.Add(RosAt(q - nr * (T / 2f), yt)); us.Add(s);
                    }
                    var o = NewObj();
                    GStrip(o.transform, rb, rt, us, mStone, new Vector2(0.5f, 1f));
                    GStrip(o.transform, bb, bt, us, mStone, new Vector2(0.5f, 1f));
                    GStrip(o.transform, rt, bt, us, mStone, new Vector2(0.5f, 1f));
                    foreach (int e in new[] { 0, ns })
                        GStrip(o.transform, new List<Vector3> { rb[e], bb[e] }, new List<Vector3> { rt[e], bt[e] }, new List<float> { 0f, T }, mStone, new Vector2(0.5f, 1f));
                    GMerge(o, GatePrefix + "Duvar_" + w.ad); nObj++;
                }
            }

            // resample a polyline every `step` metres: points, ground (Unity y), direction
            List<(Vector2 q, float g, Vector2 d, float s)> Resample(float[] xy, float step, string what)
            {
                var P = XyList(xy); var l = new List<(Vector2, float, Vector2, float)>();
                var s0 = new List<float> { 0f }; for (int i = 1; i < P.Count; i++) s0.Add(s0[i - 1] + (P[i] - P[i - 1]).magnitude);
                float total = s0[s0.Count - 1]; int ns = Mathf.Max(1, Mathf.CeilToInt(total / step));
                for (int j = 0; j <= ns; j++)
                {
                    float s = total * j / ns; int i = 1; while (i < P.Count - 1 && s0[i] < s) i++;
                    var q = Vector2.Lerp(P[i - 1], P[i], Mathf.InverseLerp(s0[i - 1], s0[i], s)); float g = GateGround(q.x, q.y);
                    if (float.IsNaN(g)) { miss++; notes.Add($"{what} s={s:F0}"); if (l.Count == 0) continue; g = l[l.Count - 1].Item2; }
                    l.Add((q, g, (P[i] - P[i - 1]).normalized, s));
                }
                return l;
            }

            // guardrail: posts every 2 m, W-beam rail 0.45..0.77 m on the road side (left of the drawing direction)
            foreach (var r in n.korkuluklar ?? new NesneCizgi[0])
            {
                var pts = Resample(r.xy, 2.0f, "korkuluk " + r.ad); if (pts.Count < 2) continue;
                var o = NewObj();
                for (int i = 0; i < pts.Count; i++)
                {
                    var (q, g, d, _) = pts[i]; var F = RosDir(d);
                    GBox(o.transform, RosAt(q, g + 0.225f), F, new Vector3(0.12f, 1.05f, 0.08f), mSteel);
                    if (i == 0) continue;
                    var (q0, g0, d0, _) = pts[i - 1]; var nl0 = new Vector2(-d0.y, d0.x) * 0.1f; var nl = new Vector2(-d.y, d.x) * 0.1f;
                    GBeam(o.transform, RosAt(q0 + nl0, g0 + 0.61f), RosAt(q + nl, g + 0.61f), 0.05f, 0.32f, mSteel);
                }
                GMerge(o, GatePrefix + "Korkuluk_" + r.ad); nObj++;
            }

            // wire fence: posts every 2.5 m, top rail, see-through mesh (alpha cut-out, 1 m texture tile)
            if (NLen(n.citler) > 0)
            {
                var mMesh = GateMat("TelOrgu", Color.white, 0.4f, 0.5f, GateTex("TelOrgu", 256, 256, FenceMesh, true, true), true);
                foreach (var c in n.citler)
                {
                    var pts = Resample(c.xy, 2.5f, "çit " + c.ad); if (pts.Count < 2) continue;
                    float H = c.boy > 0f ? c.boy : 2f; var o = NewObj();
                    var bot = new List<Vector3>(); var top = new List<Vector3>(); var us = new List<float>();
                    for (int i = 0; i < pts.Count; i++)
                    {
                        var (q, g, _, s) = pts[i];
                        GRod(o.transform, RosAt(q, g - 0.3f), RosAt(q, g + H), 0.03f, mFencePost);
                        if (i > 0) GRod(o.transform, RosAt(pts[i - 1].q, pts[i - 1].g + H - 0.03f), RosAt(q, g + H - 0.03f), 0.02f, mFencePost);
                        bot.Add(RosAt(q, g - 0.05f)); top.Add(RosAt(q, g + H - 0.03f)); us.Add(s);
                    }
                    GStrip(o.transform, bot, top, us, mMesh, Vector2.one);
                    GMerge(o, GatePrefix + "Cit_" + c.ad); nObj++;
                }
            }

            Physics.SyncTransforms();
            L($"Nizamiye nesneleri: {nObj} nesne ({NLen(n.bariyerler)} bariyer, {NLen(n.bayraklar)} bayrak, {NLen(n.kulubeler)} kulübe, " +
              $"{NLen(n.tabelalar)} tabela, {NLen(n.kutular)} kutu, {NLen(n.panolar)} pano, {NLen(n.cop_kutulari)} çöp kutusu, {NLen(n.yuvarlak_calilar)} çalı, {NLen(n.sus_agaclari)} süs ağacı, {NLen(n.duvarlar)} duvar, {NLen(n.korkuluklar)} korkuluk, {NLen(n.citler)} çit)" +
              (miss > 0 ? $"; UYARI: zemin bulunamayan {miss} nokta: {string.Join(", ", notes.Take(20))}" : ""));
        }

        // ================= median island (refüj) =================
        // Double-sided mesh (vertical curb faces): the back faces get their own vertices so the normals do not cancel.
        static GameObject MakeDoubleSidedMesh(string name, float[] v, int[] t, Transform parent, Material mat)
        {
            int n = v.Length / 3;
            var pos = new Vector3[2 * n]; var uv = new Vector2[2 * n];
            for (int i = 0; i < n; i++)
            {
                var p = RosToUnity(new Vector3(v[3 * i], v[3 * i + 1], v[3 * i + 2]));
                pos[i] = p; pos[i + n] = p;
                uv[i] = uv[i + n] = new Vector2(v[3 * i] + v[3 * i + 1], v[3 * i + 2]);
            }
            var tri = new int[2 * t.Length];
            for (int k = 0; k + 2 < t.Length; k += 3)
            {
                tri[k] = t[k]; tri[k + 1] = t[k + 1]; tri[k + 2] = t[k + 2];
                tri[t.Length + k] = t[k] + n; tri[t.Length + k + 1] = t[k + 2] + n; tri[t.Length + k + 2] = t[k + 1] + n;
            }
            var mesh = new Mesh { name = name, indexFormat = UnityEngine.Rendering.IndexFormat.UInt32 };
            mesh.vertices = pos; mesh.uv = uv; mesh.triangles = tri;
            mesh.RecalculateNormals(); mesh.RecalculateTangents(); mesh.RecalculateBounds();
            var go = new GameObject(name);
            go.transform.SetPositionAndRotation(Vector3.zero, Quaternion.identity);
            go.transform.SetParent(parent, true);
            go.AddComponent<MeshFilter>().sharedMesh = mesh;
            go.AddComponent<MeshRenderer>().sharedMaterial = mat;
            go.AddComponent<MeshCollider>().sharedMesh = mesh;
            return go;
        }

        static Material LampMaterial(Material like)
        {
            var m = AssetDatabase.LoadAssetAtPath<Material>(MedianLampMatPath);
            if (m != null) return m;
            m = new Material(like) { name = "Refuj_Lamba" };
            foreach (var tex in new[] { "_BaseColorMap", "_NormalMap", "_MaskMap" }) if (m.HasProperty(tex)) m.SetTexture(tex, null);
            if (m.HasProperty("_BaseColor")) m.SetColor("_BaseColor", new Color(0.92f, 0.92f, 0.90f));
            if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", 0.45f);
            if (m.HasProperty("_Metallic")) m.SetFloat("_Metallic", 0.3f);
            ResetHdrpKeywords(m);
            if (!AssetDatabase.IsValidFolder(MatDir)) AssetDatabase.CreateFolder("Assets/Beytepe", "Materials");
            AssetDatabase.CreateAsset(m, MedianLampMatPath);
            return m;
        }

        static void ApplyRefuj(GameObject model, Transform parent, RefujVeri d)
        {
            var matSide = FindModelMaterial(model, n => n.IndexOf("Sidewalk", StringComparison.OrdinalIgnoreCase) >= 0)
                          ?? FindModelMaterial(model, n => n.IndexOf("Curb", StringComparison.OrdinalIgnoreCase) >= 0);
            // curb face: grey concrete like the real median (the yellow line next to it is the road marking, already in the model)
            var matCurb = FindModelMaterial(model, n => n.IndexOf("Curb", StringComparison.OrdinalIgnoreCase) >= 0) ?? matSide;
            var matGrass = FindModelMaterial(model, n => n.IndexOf("Grass", StringComparison.OrdinalIgnoreCase) >= 0);
            if (matSide == null || matGrass == null) { L("UYARI: Refüj: kaldırım/çim malzemesi bulunamadı, atlandı"); return; }

            MakeOverlayMesh("Refuj_Kaldirim", d.kaldirim_v, d.kaldirim_t, model.transform, matSide, true);
            MakeOverlayMesh("Refuj_Cim", d.cim_v, d.cim_t, model.transform, matGrass, true);
            MakeDoubleSidedMesh("Refuj_Bordur", d.bordur_v, d.bordur_t, model.transform, matCurb);
            var matAsph = FindModelMaterial(model, n => n.IndexOf("Asphalt", StringComparison.OrdinalIgnoreCase) >= 0);
            if (matAsph != null && d.asfalt_v != null && d.asfalt_v.Length > 0)   // lane edge -> curb strip (curb stands back)
                MakeOverlayMesh("Refuj_Asfalt", d.asfalt_v, d.asfalt_t, model.transform, matAsph, true);
            Physics.SyncTransforms();
            var border = XyList(d.sinir_xy);
            SinkUnderMedian(model, IslandRings(d));

            // RoadRunner trees / bushes inside the median and every other raised island (south median, gate islands,
            // sidewalks) are hidden (measured trees are placed instead)
            int nHidden = 0; var allRings = IslandRings(d);
            foreach (var t in model.GetComponentsInChildren<Transform>(true))
            {
                var nm = t.name;
                if (!(nm.StartsWith("Bush_") || nm.StartsWith("Eucalyptus_")) || !nm.EndsWith("Node")) continue;
                if (t.parent != null && (t.parent.name.StartsWith("Bush_") || t.parent.name.StartsWith("Eucalyptus_"))) continue;
                if (!t.gameObject.activeSelf) continue;
                var tb = TreeBase(t, null); if (tb == null) continue;      // where the trunk stands, not the transform
                var r = UnityToRos(tb.Value.c);
                var r2 = new Vector2(r.x, r.y);
                if (allRings.Any(rg => InPoly(r2, rg))) { t.gameObject.SetActive(false); nHidden++; }
            }

            // trees: RoadRunner templates (eucalyptus / bush) scaled to the measured height
            int nT = 0, nB = 0;
            if (d.agaclar != null && d.agaclar.Length > 0)
            {
                AssetDatabase.ImportAsset(FbxPath, ImportAssetOptions.ForceSynchronousImport);
                var fbx = AssetDatabase.LoadAssetAtPath<GameObject>(FbxPath);
                var tmp = (GameObject)PrefabUtility.InstantiatePrefab(fbx);
                Transform Pick(string key, int minR, int maxR)
                {
                    foreach (var t in tmp.GetComponentsInChildren<Transform>(true))
                    {
                        if (t.name.IndexOf(key, StringComparison.OrdinalIgnoreCase) < 0) continue;
                        if (t.name.IndexOf("Leaves", StringComparison.OrdinalIgnoreCase) >= 0 || t.name.IndexOf("Trunk", StringComparison.OrdinalIgnoreCase) >= 0) continue;
                        int n = t.GetComponentsInChildren<MeshRenderer>(true).Length;
                        if (n >= minR && n <= maxR) return t;
                    }
                    return null;
                }
                (Quaternion rot, Vector3 scale, Vector3 baseOff, float height, float width) Measure(Transform t)
                {
                    var rs = t.GetComponentsInChildren<Renderer>(true);
                    var b = rs[0].bounds; foreach (var rr in rs) b.Encapsulate(rr.bounds);
                    var trunk = rs.FirstOrDefault(rr => rr.name.IndexOf("Trunk", StringComparison.OrdinalIgnoreCase) >= 0);
                    var c = trunk != null ? trunk.bounds.center : b.center;
                    return (t.rotation, t.lossyScale, new Vector3(c.x, b.min.y, c.z) - t.position, b.size.y, Mathf.Max(b.size.x, b.size.z));
                }
                var tTree = Pick("Eucalyptus", 2, 3); var tBush = Pick("Bush", 1, 2);
                var mTree = tTree != null ? Measure(tTree) : default; var mBush = tBush != null ? Measure(tBush) : default;
                var root = new GameObject("Refuj_Agaclar"); root.transform.SetParent(parent, false);
                var rng = new System.Random(4242);
                foreach (var a in d.agaclar)
                {
                    bool isTree = a.tur == "agac" || tBush == null;
                    var tpl = isTree ? tTree : tBush; if (tpl == null) continue;
                    var m = isTree ? mTree : mBush;
                    var holder = new GameObject(isTree ? "agac" : "cali");
                    holder.transform.SetParent(root.transform, false);
                    holder.transform.position = RosToUnity(new Vector3(a.x, a.y, a.z));
                    var copy = UnityEngine.Object.Instantiate(tpl.gameObject, holder.transform);
                    var yaw = Quaternion.Euler(0f, (float)(rng.NextDouble() * 360.0), 0f);
                    copy.transform.rotation = yaw * m.rot; copy.transform.localScale = m.scale;
                    copy.transform.localPosition = -(yaw * m.baseOff);
                    float s = Mathf.Clamp(a.boy / Mathf.Max(m.height, 0.1f), 0.2f, 6f);
                    float sh = Mathf.Clamp(2f * a.tac / Mathf.Max(m.width, 0.1f), 0.6f * s, 1.6f * s);
                    holder.transform.localScale = new Vector3(sh, s, sh);
                    if (isTree) nT++; else nB++;
                }
                UnityEngine.Object.DestroyImmediate(tmp);
                ApplyFallbackMaterials(root);
            }

            // two-arm lamps: white pole, two curved arms across the road direction, a head at each end
            int nL = 0;
            if (d.lambalar != null && d.lambalar.Length > 0)
            {
                var matLamp = LampMaterial(matSide);
                var root = new GameObject("Refuj_Lambalar"); root.transform.SetParent(parent, false);
                void Seg(Transform p, Vector3 a, Vector3 b, float r)
                {
                    var c = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                    UnityEngine.Object.DestroyImmediate(c.GetComponent<Collider>());
                    c.transform.SetParent(p, false);
                    c.transform.position = (a + b) / 2f;
                    c.transform.up = (b - a).normalized;
                    c.transform.localScale = new Vector3(2f * r, (b - a).magnitude / 2f, 2f * r);
                    c.GetComponent<MeshRenderer>().sharedMaterial = matLamp;
                }
                foreach (var l in d.lambalar)
                {
                    var lamp = new GameObject("lamba_" + l.ad); lamp.transform.SetParent(root.transform, false);
                    var basePt = RosToUnity(new Vector3(l.x, l.y, l.z));
                    if (Physics.Raycast(basePt + Vector3.up * 3f, Vector3.down, out var hit, 6f)) basePt.y = hit.point.y;
                    float H = l.boy, armStart = H - 2.2f;
                    Seg(lamp.transform, basePt + Vector3.down * 0.3f, basePt + Vector3.up * armStart, 0.09f);
                    float th = l.yol_yonu_deg * Mathf.Deg2Rad;
                    foreach (var side in new[] { -1f, 1f })
                    {
                        // arm direction: across the road (left normal in ROS = (-sin, cos))
                        var dirRos = new Vector3(-Mathf.Sin(th), Mathf.Cos(th), 0f) * side;
                        var dirU = RosToUnity(dirRos).normalized; dirU.y = 0f; dirU.Normalize();
                        Vector3 prev = basePt + Vector3.up * armStart;
                        const int K = 8;
                        for (int k = 1; k <= K; k++)
                        {
                            float u = k / (float)K;
                            // quarter ellipse: up first, then outwards
                            var p = basePt + Vector3.up * (armStart + 2.2f * Mathf.Sin(u * Mathf.PI / 2f)) + dirU * (l.kol * (1f - Mathf.Cos(u * Mathf.PI / 2f)));
                            Seg(lamp.transform, prev, p, 0.06f); prev = p;
                        }
                        var head = GameObject.CreatePrimitive(PrimitiveType.Cube);
                        UnityEngine.Object.DestroyImmediate(head.GetComponent<Collider>());
                        head.transform.SetParent(lamp.transform, false);
                        head.transform.position = prev + dirU * 0.25f + Vector3.down * 0.06f;
                        head.transform.rotation = Quaternion.LookRotation(dirU, Vector3.up);
                        head.transform.localScale = new Vector3(0.28f, 0.12f, 0.6f);
                        head.GetComponent<MeshRenderer>().sharedMaterial = matLamp;
                    }
                    // merge the parts into one readable mesh (the RGL lidar and the point-cloud export can read it)
                    var parts = lamp.GetComponentsInChildren<MeshFilter>(true);
                    var w2l = lamp.transform.worldToLocalMatrix;
                    var ci = parts.Select(f => new CombineInstance { mesh = f.sharedMesh, transform = w2l * f.transform.localToWorldMatrix }).ToArray();
                    var mesh = new Mesh { name = "lamba_" + l.ad, indexFormat = UnityEngine.Rendering.IndexFormat.UInt32 };
                    mesh.CombineMeshes(ci, true, true); mesh.RecalculateBounds();
                    foreach (var f in parts) UnityEngine.Object.DestroyImmediate(f.gameObject);
                    lamp.AddComponent<MeshFilter>().sharedMesh = mesh;
                    lamp.AddComponent<MeshRenderer>().sharedMaterial = matLamp;
                    nL++;
                }
            }
            L($"Refüj: kaldırım {d.kaldirim_t.Length / 3}, çim {d.cim_t.Length / 3}, bordür {d.bordur_t.Length / 3} üçgen; " +
              $"{nHidden} RoadRunner ağacı gizlendi, {nT} ağaç + {nB} çalı eklendi, {nL} lamba eklendi");
        }

        // RoadRunner ground inside the median is lowered to 8 cm under the new curbs / grass wherever it pokes through
        // (it is never raised). Triangles touching the median are split to <= 1 m first so the edit stays local.
        const string SunkSuffix = "_refujalti";
        static List<List<Vector2>> IslandRings(RefujVeri d)
        {
            var l = new List<List<Vector2>> { XyList(d.sinir_xy) };
            if (d.ek_sinirlar != null) foreach (var a in d.ek_sinirlar) if (a.xy != null && a.xy.Length >= 6) l.Add(XyList(a.xy));
            return l;
        }

        static void SinkUnderMedian(GameObject model, List<List<Vector2>> rings)
        {
            var all = rings.SelectMany(r => r).ToList();
            var box = RosBox(all.Min(p => p.x) - 1f, all.Max(p => p.x) + 1f, all.Min(p => p.y) - 1f, all.Max(p => p.y) + 1f);
            var masks = rings.Select(r => new PolyMaske(r)).ToList();
            bool In(Vector3 w) { var r = UnityToRos(w); foreach (var m in masks) if (m.In(r.x, r.y)) return true; return false; }
            bool Touches(Vector3 wa, Vector3 wb)
            {
                if (!box.Contains(wa) && !box.Contains(wb)) return false;
                int n = Mathf.Max(1, Mathf.CeilToInt(Vector3.Distance(wa, wb) / 0.5f));
                for (int k = 0; k <= n; k++) if (In(Vector3.Lerp(wa, wb, k / (float)n))) return true;
                return false;
            }
            float? MedianTop(Vector3 w)   // highest refüj surface above / below this point
            {
                float? best = null;
                foreach (var h in Physics.RaycastAll(new Vector3(w.x, w.y + 20f, w.z), Vector3.down, 40f, ~0, QueryTriggerInteraction.Ignore))
                    if (h.collider.name.StartsWith("Refuj_") && (best == null || h.point.y > best)) best = h.point.y;
                return best;
            }
            int nMesh = 0, nSplit = 0, nLow = 0;
            foreach (var mf in TerrainMeshes(model, box))
            {
                var em = new DuzenlenenMesh(mf, null);
                em.Subdivide((wa, wb, wc) => Touches(wa, wb) || Touches(wb, wc) || Touches(wc, wa) || In((wa + wb + wc) / 3f));
                var changed = new bool[em.pos.Count]; int nch = 0;
                for (int v = 0; v < em.pos.Count; v++)
                {
                    var w = em.W(v);
                    if (!In(w)) continue;
                    var top = MedianTop(w);
                    if (top == null || w.y <= top.Value - 0.08f) continue;
                    w.y = top.Value - 0.08f; em.SetW(v, w); changed[v] = true; nch++;
                }
                if (nch == 0 && em.nSplit == 0) continue;
                em.Commit(SunkSuffix, nch > 0 ? changed : null, null);
                nMesh++; nSplit += em.nSplit; nLow += nch;
            }
            L($"Refüj: altındaki RoadRunner zemini: {nMesh} mesh, {nSplit} üçgen bölündü, {nLow} köşe kaldırım/çim yüzeyinin 8 cm altına indirildi");
        }

        // ================= trees =================
        // Every tree / bush of the WHOLE map (RoadRunner ones and the measured median trees) is checked where its trunk
        // stands (the transform of a RoadRunner tree is not where it stands; the lowest vertices of the trunk mesh are):
        //  * the trunk foot (centre + 8 points on its edge) is on a road, curb, sidewalk, gutter, marking, bridge or one of
        //    our asphalt / curb / marking surfaces -> hidden (user 2026-11-15: "kaldırıma denk gelen ağaç varsa kaldır");
        //  * otherwise the tree is moved so that its foot is 3 cm under the LOWEST ground point under the trunk: no gap
        //    between ground and tree anywhere (user: "yer ile ağaç arasında asla boşluk kalmasın"). A tree buried more than
        //    1 m is raised the same way;
        //  * in the gate area the trees inside the "no tree" mask (asphalt, islands) are hidden as before.
        // The surface type comes from the material of the hit triangle (edited meshes keep their materials per triangle),
        // otherwise from the object name.
        static readonly Dictionary<Mesh, Vector3[]> TreeVerts = new Dictionary<Mesh, Vector3[]>();

        // trunk foot of a tree: centre (Unity, y = lowest vertex), radius of the foot ring
        static (Vector3 c, float rad)? TreeBase(Transform t, List<Vector3> buf)
        {
            var mfs = t.GetComponentsInChildren<MeshFilter>(true).Where(m => m.sharedMesh != null).ToArray();
            if (mfs.Length == 0) return null;
            var trunk = mfs.Where(m => m.name.IndexOf("Trunk", StringComparison.OrdinalIgnoreCase) >= 0).ToArray();
            if (trunk.Length > 0) mfs = trunk;
            buf = buf ?? new List<Vector3>(); buf.Clear();
            foreach (var mf in mfs)
            {
                var mesh = mf.sharedMesh;
                if (!TreeVerts.TryGetValue(mesh, out var v)) { v = mesh.isReadable ? mesh.vertices : null; TreeVerts[mesh] = v; }
                var M = mf.transform.localToWorldMatrix;
                if (v != null) foreach (var p in v) buf.Add(M.MultiplyPoint3x4(p));
                else { var b = mf.GetComponent<Renderer>()?.bounds; if (b != null) buf.Add(new Vector3(b.Value.center.x, b.Value.min.y, b.Value.center.z)); }
            }
            if (buf.Count == 0) return null;
            float minY = buf.Min(p => p.y); float sx = 0, sz = 0; int n = 0;
            foreach (var p in buf) if (p.y < minY + 0.25f) { sx += p.x; sz += p.z; n++; }
            var c = new Vector3(sx / n, minY, sz / n); float rad = 0f;
            foreach (var p in buf) if (p.y < minY + 0.25f) rad = Mathf.Max(rad, Mathf.Sqrt((p.x - c.x) * (p.x - c.x) + (p.z - c.z) * (p.z - c.z)));
            return (c, Mathf.Clamp(rad, 0.1f, 1.0f));
        }

        static string HitMaterial(RaycastHit h)
        {
            if (!(h.collider is MeshCollider mc) || mc.sharedMesh == null || h.triangleIndex < 0) return null;
            var mr = mc.GetComponent<MeshRenderer>(); if (mr == null) return null;
            var mesh = mc.sharedMesh; var mats = mr.sharedMaterials;
            if (mats.Length == 1) return mats[0] != null ? mats[0].name : null;
            if (mesh.subMeshCount != mats.Length) return null;
            long idx = 3L * h.triangleIndex, acc = 0;
            for (int s = 0; s < mesh.subMeshCount; s++)
            {
                long cnt = mesh.GetIndexCount(s);
                if (idx < acc + cnt) return mats[s] != null ? mats[s].name : null;
                acc += cnt;
            }
            return null;
        }

        // null = ground (grass, terrain); otherwise what the tree stands on
        static string HardSurface(RaycastHit h)
        {
            var n = h.collider.name;
            if (n.StartsWith("Refuj_Cim")) return null;
            if (n.StartsWith("Refuj_") || n.StartsWith("Nizamiye_") || n.StartsWith("Kasis")) return n;
            if (FullName(h.collider.transform).IndexOf("Bridge", StringComparison.OrdinalIgnoreCase) >= 0) return "Bridge";
            var mat = HitMaterial(h);
            if (mat != null) return IsRoadLikeMat(mat) || IsMarkingMat(mat) ? mat : null;
            var full = FullName(h.collider.transform);
            foreach (var k in new[] { "Sidewalk", "Curb", "Gutter", "Marking", "Roads_Road", "Bridge" })
                if (full.IndexOf(k, StringComparison.OrdinalIgnoreCase) >= 0) return k;
            return null;
        }

        static void FixTrees(GameObject model, Transform parent, DuzenlemeVeri d)
        {
            var g = Has(d.nizamiye) ? new NizamiyeIzgara(d.nizamiye) : null;
            Physics.SyncTransforms();
            var trees = new List<Transform>();
            foreach (var t in model.GetComponentsInChildren<Transform>(true))
            {
                var nm = t.name;
                if (!(nm.StartsWith("Bush_") || nm.StartsWith("Eucalyptus_")) || !nm.EndsWith("Node")) continue;
                if (t.parent != null && (t.parent.name.StartsWith("Bush_") || t.parent.name.StartsWith("Eucalyptus_"))) continue;
                if (t.gameObject.activeInHierarchy) trees.Add(t);
            }
            int nRR = trees.Count;
            foreach (var root in parent.GetComponentsInChildren<Transform>(true).Where(x => x.name == "Refuj_Agaclar"))
                foreach (Transform h in root) if (h.gameObject.activeInHierarchy) trees.Add(h);

            var buf = new List<Vector3>(4096);
            var hidden = new Dictionary<string, int>(); int nMask = 0, nDown = 0, nUp = 0, nNoHit = 0; float maxGap = 0f; string maxAt = "";
            var gaps = new List<string>();
            foreach (var t in trees)
            {
                var tb = TreeBase(t, buf); if (tb == null) continue;
                var (c, rad) = tb.Value; var ros = UnityToRos(c);
                if (g != null && g.Maske(g.agacsiz, ros.x, ros.y)) { t.gameObject.SetActive(false); nMask++; continue; }
                string hard = null; float hmin = float.MaxValue; int nHit = 0;
                for (int k = -1; k < 8 && hard == null; k++)
                {
                    var p = k < 0 ? c : c + rad * new Vector3(Mathf.Cos(k * Mathf.PI / 4f), 0f, Mathf.Sin(k * Mathf.PI / 4f));
                    RaycastHit best = default; bool found = false;
                    foreach (var hh in Physics.RaycastAll(new Vector3(p.x, c.y + 1.5f, p.z), Vector3.down, 40f, ~0, QueryTriggerInteraction.Ignore))
                    {
                        if (hh.collider.transform.IsChildOf(t)) continue;
                        if (!found || hh.distance < best.distance) { best = hh; found = true; }
                    }
                    if (!found) continue;
                    nHit++; hard = HardSurface(best);
                    if (hard == null) hmin = Mathf.Min(hmin, best.point.y);
                }
                if (hard != null)
                {
                    t.gameObject.SetActive(false);
                    hidden[hard] = hidden.TryGetValue(hard, out var cnt) ? cnt + 1 : 1;
                    continue;
                }
                if (nHit == 0 || hmin == float.MaxValue) { nNoHit++; continue; }
                float gap = c.y - hmin;
                if (gap > -0.01f || gap < -1.0f)
                {
                    t.position += Vector3.up * (hmin - 0.03f - c.y);
                    if (gap > -0.01f) nDown++; else nUp++;
                    if (gap > 0.1f) gaps.Add($"({ros.x:F1}, {ros.y:F1}) {gap:F2} m");
                    if (gap > maxGap) { maxGap = gap; maxAt = $"({ros.x:F1}, {ros.y:F1})"; }
                }
            }
            L($"Ağaçlar (bütün harita): {nRR} RoadRunner + {trees.Count - nRR} ölçülmüş ağaç/çalı tarandı. Gizlenen: nizamiye asfalt/ada maskesi {nMask}, "
              + "gövdesi yüzey üstünde " + (hidden.Count == 0 ? "0" : string.Join(", ", hidden.OrderByDescending(kv => kv.Value).Select(kv => $"{kv.Key} {kv.Value}"))));
            L($"Ağaçlar: zemine indirilen {nDown} (10 cm'den büyük boşluk {gaps.Count}, en büyük {maxGap:F2} m {maxAt}), 1 m'den derin gömülüp çıkarılan {nUp}, altında zemin bulunamayan {nNoHit}");
            if (gaps.Count > 0) L("  boşluğu 10 cm'den büyük olanlar: " + string.Join("; ", gaps.Take(40)) + (gaps.Count > 40 ? " ..." : ""));
            TreeVerts.Clear();
        }

        // ================= lane marking colours =================
        // RoadRunner drew the median road's lines the other way round (dashed lane line yellow, edge lines white). Each
        // marking triangle in the region takes the colour of the lanelet line it lies on (within 0.6 m and running along it):
        // solid -> yellow, dashed -> white. Other markings (crosswalks, arrows, stop lines) do not run along a line: unchanged.
        static void RecolorMarkings(GameObject model, CizgiRenkVeri r)
        {
            bool Yellow(string n) => n.IndexOf("Yellow", StringComparison.OrdinalIgnoreCase) >= 0;
            var matW = FindModelMaterial(model, n => IsMarkingMat(n) && !Yellow(n));
            var matY = FindModelMaterial(model, n => IsMarkingMat(n) && Yellow(n));
            if (matW == null || matY == null) { L("UYARI: Çizgi renkleri: beyaz/sarı çizgi malzemesi bulunamadı, atlandı"); return; }
            var region = XyList(r.bolge_xy); var mask = new PolyMaske(region, 0.25f);
            var box = RosBox(region.Min(p => p.x), region.Max(p => p.x), region.Min(p => p.y), region.Max(p => p.y));
            // segments in a 2 m grid (each one is entered in every cell its box + 0.6 m touches)
            var segs = new List<(Vector2 a, Vector2 b, bool yellow)>();
            void Add(float[] f, bool y) { if (f != null) for (int i = 0; i + 3 < f.Length; i += 4) segs.Add((new Vector2(f[i], f[i + 1]), new Vector2(f[i + 2], f[i + 3]), y)); }
            Add(r.sari_xy, true); Add(r.beyaz_xy, false);
            const float C = 2f, maxD = 0.6f;
            var grid = new Dictionary<long, List<int>>();
            long Key(int i, int j) => ((long)i << 32) ^ (uint)j;
            for (int k = 0; k < segs.Count; k++)
            {
                var (a, b, _) = segs[k];
                int i0 = Mathf.FloorToInt((Mathf.Min(a.x, b.x) - maxD) / C), i1 = Mathf.FloorToInt((Mathf.Max(a.x, b.x) + maxD) / C);
                int j0 = Mathf.FloorToInt((Mathf.Min(a.y, b.y) - maxD) / C), j1 = Mathf.FloorToInt((Mathf.Max(a.y, b.y) + maxD) / C);
                for (int i = i0; i <= i1; i++) for (int j = j0; j <= j1; j++)
                    { if (!grid.TryGetValue(Key(i, j), out var l)) grid[Key(i, j)] = l = new List<int>(); l.Add(k); }
            }
            int Nearest(Vector2 p, Vector2 dir)   // -1: none, 0: white, 1: yellow
            {
                if (!grid.TryGetValue(Key(Mathf.FloorToInt(p.x / C), Mathf.FloorToInt(p.y / C)), out var l)) return -1;
                float best = maxD; int res = -1;
                foreach (var k in l)
                {
                    var (a, b, y) = segs[k]; var ab = b - a; float L2 = ab.sqrMagnitude; if (L2 < 1e-6f) continue;
                    float t = Mathf.Clamp01(Vector2.Dot(p - a, ab) / L2); float dd = Vector2.Distance(a + t * ab, p);
                    if (dd >= best || Mathf.Abs(Vector2.Dot(dir, ab / Mathf.Sqrt(L2))) < 0.8f) continue;
                    best = dd; res = y ? 1 : 0;
                }
                return res;
            }
            int nMesh = 0, nToW = 0, nToY = 0, nSame = 0, nOther = 0;
            foreach (var mf in TerrainMeshes(model, box))
            {
                var mr = mf.GetComponent<MeshRenderer>(); var mats = mr.sharedMaterials.ToList();
                if (!mats.Any(m => m != null && IsMarkingMat(m.name))) continue;
                var em = new DuzenlenenMesh(mf, null);
                int wIdx = mats.FindIndex(m => m != null && IsMarkingMat(m.name) && !Yellow(m.name));
                int yIdx = mats.FindIndex(m => m != null && IsMarkingMat(m.name) && Yellow(m.name));
                var toW = new List<int>(); var toY = new List<int>();
                for (int s = 0; s < em.tris.Length && s < mats.Count; s++)
                {
                    if (mats[s] == null || !IsMarkingMat(mats[s].name)) continue;
                    bool isY = Yellow(mats[s].name);
                    var t = em.tris[s]; var keep = new List<int>(t.Count);
                    for (int k = 0; k + 2 < t.Count; k += 3)
                    {
                        var wa = em.W(t[k]); var wb = em.W(t[k + 1]); var wc = em.W(t[k + 2]);
                        var ra = UnityToRos(wa); var rb = UnityToRos(wb); var rc = UnityToRos(wc);
                        var c = new Vector2((ra.x + rb.x + rc.x) / 3f, (ra.y + rb.y + rc.y) / 3f);
                        int target = -1;
                        if (mask.In(c.x, c.y))
                        {
                            // direction of the triangle = its longest edge
                            Vector2 e1 = new Vector2(rb.x - ra.x, rb.y - ra.y), e2 = new Vector2(rc.x - rb.x, rc.y - rb.y), e3 = new Vector2(ra.x - rc.x, ra.y - rc.y);
                            var e = e1.sqrMagnitude >= e2.sqrMagnitude && e1.sqrMagnitude >= e3.sqrMagnitude ? e1 : (e2.sqrMagnitude >= e3.sqrMagnitude ? e2 : e3);
                            if (e.sqrMagnitude > 1e-6f) target = Nearest(c, e.normalized);
                            if (target < 0) nOther++;
                        }
                        if (target < 0 || (target == 1) == isY) { if (target >= 0) nSame++; keep.Add(t[k]); keep.Add(t[k + 1]); keep.Add(t[k + 2]); continue; }
                        (target == 1 ? toY : toW).AddRange(new[] { t[k], t[k + 1], t[k + 2] });
                    }
                    em.tris[s] = keep;
                }
                if (toW.Count == 0 && toY.Count == 0) continue;
                em.AddTo(mats, ref yIdx, matY, toY); em.AddTo(mats, ref wIdx, matW, toW);
                em.Commit("_renk", null, mats);
                nMesh++; nToW += toW.Count / 3; nToY += toY.Count / 3;
            }
            L($"Çizgi renkleri: {nMesh} mesh, {nToW} üçgen sarıdan beyaza, {nToY} üçgen beyazdan sarıya; {nSame} üçgen zaten doğru renkte, {nOther} çizgi üçgeni bir şerit çizgisine oturmadı (geçit/ok vb., dokunulmadı)");
        }

        // ================= point cloud of the edited regions =================
        // Called right before the scene is saved: area-weighted random samples of every visible surface in the regions
        // (ground, road, trees, buildings, bumps, shelter, lamps), written as float32 x, y, z in the ROS map frame.
        // The RoadRunner ground pushed under the median is skipped (a real lidar cannot see it).
        static List<List<Vector2>> CloudRegions(DuzenlemeVeri d)
        {
            var regs = new List<List<Vector2>>();
            if (d == null) return regs;
            if (Has(d.refuj) && d.refuj.bulut_alanlari != null)
                foreach (var a in d.refuj.bulut_alanlari) if (a.xy != null && a.xy.Length >= 6) regs.Add(XyList(a.xy));
            if (regs.Count == 0 && Has(d.nizamiye) && d.nizamiye.bulut_kutu != null && d.nizamiye.bulut_kutu.Length == 4)
            {
                var k = d.nizamiye.bulut_kutu;
                regs.Add(new List<Vector2> { new Vector2(k[0], k[2]), new Vector2(k[1], k[2]), new Vector2(k[1], k[3]), new Vector2(k[0], k[3]) });
            }
            return regs;
        }

        static void DuzenlemeBulutYaz()
        {
            var d = LoadEdits();
            var regs = CloudRegions(d);
            if (regs.Count == 0) return;
            var rings = Has(d.refuj) ? IslandRings(d.refuj).Select(r => new PolyMaske(r)).ToList() : null;
            float dens = Has(d.nizamiye) ? Mathf.Max(0.5f, d.nizamiye.bulut_yogunluk) : 5f;
            float x0 = regs.SelectMany(r => r).Min(p => p.x), x1 = regs.SelectMany(r => r).Max(p => p.x);
            float y0 = regs.SelectMany(r => r).Min(p => p.y), y1 = regs.SelectMany(r => r).Max(p => p.y);
            var box = RosBox(x0, x1, y0, y1);
            bool In(Vector3 ros) { var p2 = new Vector2(ros.x, ros.y); foreach (var r in regs) if (InPoly(p2, r)) return true; return false; }
            var ego = UnityEngine.Object.FindFirstObjectByType<Awsim.Scene.AutowareSimulationDemo.EgoVehicle>();
            var rnd = new System.Random(12345);
            var outPts = new List<Vector3>(1000000); int nObj = 0, nSkip = 0;
            foreach (var mr in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsInactive.Exclude, FindObjectsSortMode.None))
            {
                if (!mr.enabled || !mr.bounds.Intersects(box)) continue;
                if (ego != null && mr.transform.IsChildOf(ego.transform)) continue;
                var mf = mr.GetComponent<MeshFilter>(); var m = mf != null ? mf.sharedMesh : null;
                if (m == null || !m.isReadable) continue;
                bool sunk = rings != null && m.name.Contains(SunkSuffix);   // later edits (speed bumps) add their own suffix
                var l2w = mr.transform.localToWorldMatrix; var vs = m.vertices; var tr = m.triangles; nObj++;
                for (int k = 0; k + 2 < tr.Length; k += 3)
                {
                    var a = l2w.MultiplyPoint3x4(vs[tr[k]]); var b = l2w.MultiplyPoint3x4(vs[tr[k + 1]]); var c = l2w.MultiplyPoint3x4(vs[tr[k + 2]]);
                    var cen = (a + b + c) / 3f;
                    if (!box.Contains(cen)) continue;
                    var rc = UnityToRos(cen);
                    if (sunk && rings.Any(rm => rm.In(rc.x, rc.y))) { nSkip++; continue; }
                    float area = Vector3.Cross(b - a, c - a).magnitude * 0.5f;
                    if (area < 1e-6f) continue;
                    if (!In(rc) && area < 4f) continue;   // small triangle whose centre is outside: skip
                    double want = area * dens; int nPts = (int)want; if (rnd.NextDouble() < want - nPts) nPts++;
                    for (int i = 0; i < nPts; i++)
                    {
                        float r1 = (float)rnd.NextDouble(), r2 = (float)rnd.NextDouble();
                        if (r1 + r2 > 1f) { r1 = 1f - r1; r2 = 1f - r2; }
                        var ros = UnityToRos(a + (b - a) * r1 + (c - a) * r2);
                        if (!In(ros)) continue;
                        outPts.Add(ros);
                    }
                }
            }
            var path = EditCloudPath;
            Directory.CreateDirectory(Path.GetDirectoryName(path));
            using (var bw = new BinaryWriter(File.Create(path)))
                foreach (var q in outPts) { bw.Write(q.x); bw.Write(q.y); bw.Write(q.z); }
            L($"Nizamiye + refüj nokta bulutu: {outPts.Count} nokta ({nObj} nesne, {dens} nokta/m², {regs.Count} bölge, kutu x {x0:F0}..{x1:F0}, y {y0:F0}..{y1:F0}; refüj altındaki {nSkip} zemin üçgeni atlandı) -> {path}");
        }
    }
}
